// index 0-5 aligns with articles no 01-06. Merged in Insight.tsx by lang+idx.
export type ProsePara = { t: string; l: number }
export type ProseSection = { h: string; ps: ProsePara[] }
export type ArticleStat = { n: number; unit: string; label: string; source: string }
export type ArticleProse = { meta: string; standfirst: string; stat?: ArticleStat; sections: ProseSection[] }

export const ARTICLE_PROSE: Record<"en" | "zh", ArticleProse[]> = {
  en: [{"meta":"8 min read · CB Insights, IDEO","standfirst":"One dazzling strength is exactly how a weak venture gets waved through, so the engine reads all three lenses at once and lets none of them see the others.","stat":{"n":42,"unit":"%","label":"of failed startups had built something with no real market need, the single most-cited reason","source":"CB Insights"},"sections":[{"h":"Three ways to fail","ps":[{"t":"Most screens collapse a startup into a single verdict, and that single number is exactly where judgement quietly dies. A venture is never simply good or bad. It is **strong on one axis and fragile on another**, and the entire job of a screen is to know which axis is which. A blended score hides that distinction on purpose: it lets a brilliant nine average out a fatal three into a comfortable six, and a comfortable six is how a doomed company gets a meeting. The moment three different kinds of risk are folded into one number, the number stops telling you anything you can act on.","l":0},{"t":"The three lenses are not an invention of ours. They come from **IDEO's Tim Brown**, who defined design thinking as the search for what sits at the intersection of the needs of people, the possibilities of technology, and the requirements of a business. IDEO drew it as three overlapping circles and called the small patch in the middle the innovation sweet spot. Desirability, Feasibility and Viability earn their place as the three axes for a blunt reason: they are **the three ways a company actually dies**. Nobody wanted it, nobody could build it, or the arithmetic never closed. Every post-mortem you will ever read is one of those three sentences wearing a different costume.","l":0},{"t":"An averaged verdict fails because reality does not average. A customer does not slightly want a product that no one can afford to deliver; the venture simply ends. **Weakness on any single axis is usually fatal on its own**, not diluted by strength elsewhere, which is the precise opposite of what a mean does to a set of numbers. Reading three lenses separately keeps each failure mode legible right up to the decision. Reading them as one number is how a fatal flaw gets quietly absorbed into a respectable-looking total, and how the people in the room end up debating a score that no longer maps to the risk in front of them.","l":0}]},{"h":"Does anyone want it","ps":[{"t":"Desirability asks the first and least forgiving question: is the need **real, sharp, and shared by enough people to pay**? Not whether the idea is clever, not whether the demo lands, but whether an actual person feels an actual pain badly enough to change what they already do today. This is the lens most founders are quietly failing when they fail. In CB Insights' analysis of startup post-mortems, **no market need is the single most-cited reason** ventures collapse, named in roughly forty-two percent of cases. The most common way to die is not being outbuilt or outspent. It is building something carefully that nobody was waiting for.","l":0},{"t":"The trap is that desirability is the easiest lens to fake to yourself. A warm demo, a few enthusiastic friends, a waitlist that costs nothing to join, all of it reads as demand and none of it is. **A vitamin loses to the aspirin someone is already reaching for**, because a nice-to-have competes with doing nothing, and doing nothing usually wins. The real test is not whether people say they like it, but whether they reorganise a slice of their day, or their budget, to get it. Enthusiasm is abundant and almost free; a changed behaviour is scarce and expensive, and only the second one is evidence.","l":0},{"t":"This is why Desirability has to be read first and read coldly. If the underlying need is weak, nothing downstream can rescue it. A flawless engineering team building a thing nobody wants just ships faster into a wall. A beautiful business model on top of an imaginary market only documents the loss more precisely. **A cold reading here caps everything above it**, which is why a serious screen refuses to let a strong team or a clever model talk it into warmth it has not earned. The need either exists or it does not, and no amount of downstream excellence gets a vote on that question.","l":0}]},{"h":"Can it be built","ps":[{"t":"Feasibility asks whether **this team can build the mechanism and ship it**, not in theory, but with the specific people, technology and time actually in the room. A plausible product on a slide is not a feasible one. The question is never whether something like this can be built by someone, somewhere, eventually; it is whether the one genuinely hard part of this specific plan has a specific, credible path, held by the specific people proposing it. Most feasibility risk hides inside that one hard part, and most pitches route around it politely instead of through it.","l":1},{"t":"The failure here is subtler than in Desirability because it hides behind competence. Teams that can build ninety percent of a product easily will often assume the last ten percent scales the same way, when that final tenth is usually the entire venture. **The hard part is load-bearing, and everything else is scaffolding**. A serious feasibility read isolates the load-bearing part and asks for evidence that this team, specifically, can carry it: a prototype, a prior shipped system, a named person who has solved exactly this before. Everything else on the roadmap is commodity work that a competent team will finish by default.","l":1},{"t":"Ambition is cheap on this axis and a working mechanism is the only currency. Vision decks describe the destination in confident prose; feasibility is entirely about the next hard step and whether it has actually been taken. **A demo that survives contact with a real input** outweighs a hundred slides of architecture, because the slides assume the hard part is solved and the demo proves it. This is the lens that separates a company from an essay. The essay is often better written. Only the company has crossed the specific gap that would have killed it, and that crossing is the only thing feasibility is looking for.","l":1}]},{"h":"Does the math close","ps":[{"t":"Viability asks whether the model **funds itself and lets the venture endure**: whether each unit sold pays for itself and then some, and whether that advantage compounds over time instead of eroding. A company can be genuinely loved and genuinely buildable and still bleed to death one unit at a time, selling a dollar of value for ninety cents and making it up, fatally, on volume. This is the lens where charisma runs out and arithmetic takes over, and it is the one founders most often defer, because it is the least flattering and the hardest to fake with a good story.","l":2},{"t":"The most quoted startup statistic is that most failures run out of money; CB Insights puts running out of capital at the top of the list, present in the large majority of shutdowns. But **running out of cash is how a startup dies, not why**. The capital drains because one of the other lenses was already broken: the need was thin, the mechanism slipped, or the unit economics never closed and every sale quietly deepened the hole. Viability is where those upstream weaknesses finally show up as an empty bank account. Reading it honestly means asking what the money is actually paying for, and whether that cost ever bends downward.","l":2},{"t":"Viability is also the lens that rewards patience and punishes wishful arithmetic. Every plan can reach profitability in a spreadsheet three years out; the honest question is which specific number, a cost, a retention curve, a price, has to move, by how much, and whether anything real is moving it yet. **A moat that compounds turns a thin early margin into an inevitability**, while a leaky one turns a healthy margin into a slow decline. The difference is not visible in this quarter's numbers. It is visible only in the direction they are travelling, which is why viability is judged less on the current figure than on its slope.","l":2}]},{"h":"Read them blind","ps":[{"t":"Now the reason all of this has to be read blind. Human judgement is contaminated by its own first impression, a bias Amos Tversky and Daniel Kahneman named in 1974: we fix on an initial value and then adjust away from it insufficiently. Show a reviewer a founder who is magnetic on stage and their estimate of the technology, the market and the economics all drift upward together, not because any evidence moved, but because **one strong signal quietly colours everything near it**. In a deal room this is simply how a great story launders a weak business, and it happens to careful people who would swear they were being objective.","l":0},{"t":"So the engine refuses to let the lenses talk to each other. **Each axis is scored by a separate reviewer, blind to the other two**, working only from the evidence that bears on its own question. The Desirability reviewer never learns that the team is world-class; the Viability reviewer never hears how much users love the product. Each renders a verdict on its own terms, and only then are the three set side by side. The payoff is precise: a brilliant answer on one axis can no longer inflate the others, so a magnetic founder still faces a cold reading of whether anyone wants the thing, and a beloved product still faces a cold reading of its economics. **Weakness stays visible instead of being absorbed** by an adjacent strength.","l":0},{"t":"Read this way, passing one lens, or even two, is not passing. A wanted product no one can build is a dream; a buildable product no one wants is a hobby; a wanted, buildable product whose economics never close is a slow, well-loved bankruptcy. **A venture has to clear all three at once**, because reality tests all three at once, and two out of three is still a failure with a good excuse. What the three blind scores buy you is not a grade but a diagnosis: they say not only whether a venture is strong, but exactly where it is thin and what would have to become true to fix it. **A low axis is a question, not a rejection**, pointing straight at the work that remains.","l":0}]}]},{"meta":"8 min read · engine sequencing logic","standfirst":"Expert judgment on the same file can swing fifty-five percent. The engine answers that noise with an order: gate every point on evidence, score each lens alone, then let the three correct one another exactly once.","stat":{"n":55,"unit":"%","label":"Median gap between two underwriters pricing the identical case","source":"Kahneman, Sibony & Sunstein, Noise (2021)"},"sections":[{"h":"Judgment runs noisy","ps":[{"t":"Ask a room of executives how far two underwriters pricing the identical case will drift apart, and they say ten percent. The real median gap is **fifty-five percent**. Same file, same company, same afternoon, and the quote swings from roughly nine thousand dollars to sixteen thousand depending only on which desk it lands on. The variation is invisible to the people living inside it, which is exactly what makes it dangerous. Nobody in that building believes they are guessing; each underwriter is certain, experienced, and wrong by a different amount. **Noise is not the exception in expert judgment; it is the default state**, and it costs a large insurer hundreds of millions a year without ever surfacing as a single obvious mistake anyone could point to and correct.","l":0},{"t":"This is not a story about insurance. It is what unstructured judgment does everywhere a human forms a holistic impression and calls it a decision. A startup evaluated by feel is a coin whose bias you cannot see: the same deck, read by the same person on two different mornings, earns two different verdicts, and the person will defend each with equal conviction. **The problem is never a lack of intelligence; it is the absence of a fixed procedure**. Talent does not remove noise. It just makes the noise more confident, and a confident wrong number is far harder to argue with than a hesitant one, because the confidence gets mistaken for evidence.","l":0},{"t":"The fix is not a smarter judge. Across 136 studies, mechanical, rule-based prediction beat expert clinical judgment about **ten percent more often** than it lost, and almost never came out substantially worse, holding across every kind of task and every level of experience. The lesson the engine takes from this is blunt: **structure outperforms intuition not because it is cleverer, but because it is consistent**. So the engine refuses to form one impression. It imposes an order. Gate the evidence, score each lens alone, then let them correct one another exactly once. The sequence is the discipline, and the discipline is what drains the noise before it ever reaches a number.","l":1}]},{"h":"Evidence gates the score","ps":[{"t":"Most reads of a startup begin with a story and then hunt for the numbers that flatter it. The engine inverts this. Before any dimension is scored, it splits every claim the founder makes into three piles: what is **known**, what is **missing**, and what still needs to be verified. The score is built on the first pile only. A vivid narrative about the market is not evidence of the market; it is a hypothesis about it, and it waits in the second pile until something real arrives to move it. The pile a claim lands in is decided before anyone looks at how persuasively it was told, which means a quiet founder with proof outranks a brilliant storyteller with none.","l":0},{"t":"Then the rule that does the heavy lifting. Anything unproven is **capped at three out of ten**. A founder can describe a market, a technical edge, or a payback curve in the most fluent language available, and the dimension still cannot climb past three until the evidence lands. This is what stops a score from being talked upward. Fluency is not traction. Confidence is not a cohort. A signed letter of intent is worth more than a hundred slides describing the demand it stands in for. The ceiling holds until a fact raises it, and no amount of eloquence counts as a fact.","l":0},{"t":"The effect is quiet but decisive. Confidence, polish, and narrative momentum, the exact qualities that win a room, carry no weight of their own. A seven means seven because the record supports it, and the distance between a capped three and an earned seven is precisely the work a founder still has to do, stated as a number rather than a vibe. This is also where the noise drains out: by **refusing to price the persuasion**, the engine removes the very space in which two honest readers would otherwise disagree by **fifty-five percent**. Two evaluators reading the same evidence with the same cap land in the same place.","l":1}]},{"h":"Each lens scored alone","ps":[{"t":"The three lenses are scored in isolation, and the order is not cosmetic. If Desirability, Feasibility, and Viability were assessed together, one strong signal would bleed into the others. A beautiful product tempts the reader to assume the economics must work; a famous founder makes the market look inevitable. Psychologists call this the **halo effect**: a single dominant impression quietly colours every other judgment, and it is precisely the mechanism that manufactures a fifty-five percent spread between two people looking at the same facts. The first thing you notice becomes the lens you unknowingly read everything else through.","l":0},{"t":"So each lens answers only its own question and borrows credibility from none of the others. Desirability asks whether anyone truly needs this. Feasibility asks whether this team can actually build and deliver it. Viability asks whether the thing survives once it exists. **Kept apart, each question is answerable; blended together, all three become a mood**. A famous founder does not make a market real, and an elegant demo does not make the unit economics close. Isolation is what keeps those facts from leaking into one another, so a strong answer to one question never becomes a borrowed answer to the next.","l":2},{"t":"There is a deeper reason to score alone. The halo effect does not just inflate a weak lens; it hides the inflation, because the reader never sees the borrowed credibility as borrowed. **A number you cannot decompose is a number you cannot trust**. Scoring each lens against its own evidence, before any of them meet, is the only way to know later which lens actually carried the verdict and which one was quietly riding on another's strength. Independence is not politeness between the lenses. It is an audit trail, and an audit trail is what lets you reopen a decision months later and see exactly why it was made.","l":1}]},{"h":"Knockouts, not averages","ps":[{"t":"Before any total is taken, knockouts are applied. A fatal flaw ends the read instead of being averaged away. If a venture is illegal, structurally unfundable, or depends on a market that does not exist, no amount of strength elsewhere buys it back. **A single zero should collapse the verdict, not dilute it**, and an average is physically incapable of expressing that. Three sevens and a zero average to a comfortable five-plus, which is exactly the reassuring number that gets a doomed company funded. The knockout runs first so the fatal flaw never gets a chance to hide inside a mean.","l":0},{"t":"This is why naive averaging fails as a method. Blending three lenses into one number hides the precise place a venture is fragile, and it lets a strong lens quietly subsidise a broken one. **Averaging is not rigour; it is rigour's costume**. It produces a clean single figure that feels objective while erasing the one distinction that matters: whether the weakness is a gap to close or a wall to hit. The tidy number is the enemy of the honest read, because tidiness is the first thing a real risk destroys, and a method that smooths risk away is optimising for comfort, not truth.","l":0},{"t":"Independence keeps the failure visible, and visible failure is the only kind worth acting on. When each lens stands on its own, a low score points at something specific: a need nobody urgently feels, a build this team cannot ship, a model that leaks money at scale. **You cannot fix an average, but you can fix a lens**. Keeping the three scores separate all the way to the end is what turns a verdict into a to-do list instead of a mood ring, and a to-do list is the only output a founder can actually use. A blended score tells you to feel worried; a separated one tells you where to go to work.","l":2}]},{"h":"Then one bounded round","ps":[{"t":"Only after the isolated scores are fixed do the lenses correct one another, once each, across six directions: D to F, D to V, F to D, F to V, V to D, and V to F, one notch at most in either direction. The lenses genuinely inform each other, and pretending otherwise would be its own distortion. **A real, urgent need can justify a harder technical build**, while weak economics rightly drags on an otherwise elegant product. The round is real, but it is bounded, and the bound is the whole point of allowing it at all. One notch is enough to register a true relationship and too small to let a halo back in through the side door.","l":0},{"t":"Reading a strong and weak pair together is where the verdict gains its edge. Strong D with weak F is **the right need at the wrong time**. Strong F with weak V is buildable but cannot survive contact with its own economics. Strong V with weak D is a beautiful spreadsheet built for a need nobody urgently has. The cross-round is what lets the engine say not just how good a venture is, but what specific kind of wrong it is when it is wrong, which is the only diagnosis a founder can act on. A single blended score can never make that distinction, because it has already thrown the shape away.","l":1},{"t":"This is the discipline that beats a gut-feel holistic read. A holistic glance mixes everything at once and calls the blend intuition; a naive average mixes everything and calls it rigour. Both throw away the structure that tells you where a company will break. **Independent first, then a single bounded round of cross-derivation, gives you both at once**: a score you can trust because nothing was talked into it, and a diagnosis you can act on because nothing was averaged out of it. That is the difference between a number and a decision, and it is the whole reason the sequence is fixed rather than left to feel. The order is not bureaucracy; it is the only thing standing between a verdict and a fifty-five percent coin toss.","l":2}]}]},{"meta":"8 min read · Trinity verdict matrix","standfirst":"Three lenses, but not three equal votes. Desirability is the gate: if nobody needs it, nothing built well enough or priced right enough can buy the deal back.","stat":{"n":43,"unit":"%","label":"of failed startups died from poor product-market fit: the market did not want what they built","source":"CB Insights, 2024 (431 VC-backed shutdowns)"},"sections":[{"h":"Need decides before anything else","ps":[{"t":"When CB Insights read the post-mortems of 431 venture-backed companies that folded after 2023, the number that should stop any investor cold was not the 70% that ran out of money. Running out of money is how a startup dies, almost never why. The why sits one layer beneath the cash: **43% failed because the market did not want what they built.** Capital is the visible symptom, the last vital sign to flatline. Absent demand is the underlying disease, and it is the single most common one on the table. A company can raise brilliantly and spend with discipline and still be building toward a customer who was never going to show up. The bank balance only tells you when the search ended, not why it was doomed from the start.","l":0},{"t":"Marc Andreessen made the same point in 2007, in the essay that first put the words product/market fit into circulation. His claim was deliberately blunt: **the market is the most important factor in a startup's success or failure.** When a great team meets a lousy market, the market wins. When a lousy team meets a great market, the market still wins. A real market pulls a product out of a company almost regardless of who is holding the pen, because unmet demand is a vacuum and something will rush to fill it. A dead market does the opposite: it absorbs any amount of talent, capital, and craftsmanship and returns nothing, because there is no vacuum for the product to fill.","l":0},{"t":"This is why a screening engine cannot treat desirability as one preference sitting alongside two others. Feasibility and viability are both questions about execution: can the thing be built, and do the numbers close once it is. Each of them quietly assumes that a buyer already exists at the far end of the transaction. **If that assumption is false, every downstream answer is answering the wrong question,** with great precision and complete irrelevance. You are no longer evaluating a weak deal that might be strengthened. You are evaluating a non-event that has been dressed up as a company, complete with a deck, a model, and a roadmap pointing at a destination no one asked to reach. The most disciplined execution in the world cannot rescue a premise that was empty to begin with, and no amount of due diligence on the how will surface a problem that lives entirely in the whether.","l":0}]},{"h":"Why D is a gate","ps":[{"t":"A product nobody wants is not a poor investment. It is not an investment at all, because there is no underlying asset for the money to attach to. You can build it flawlessly, price it to a healthy margin, and staff it with the most capable operators you can find, and you still end up holding a warehouse full of a thing the world will not reach for. Every other virtue is real and every other virtue is wasted. **Desirability is the only lens that can zero out the other two,** because it alone decides whether the other two are describing anything that exists. Feasibility and viability measure the qualities of a product; desirability measures whether the product has any reason to be measured.","l":0},{"t":"So the engine does not fold D into an average. It treats D as a gate, and a gate behaves in a fundamentally different way from a weight. A weight can always be compensated: a low score in one place is quietly offset by a high score somewhere else, and the blend hides the shortfall. A gate refuses that arithmetic. **You are either through it or you are not,** and no quantity of brilliance on the far side can move you back to the near side. The question a gate asks is not how much, but whether at all. It is the difference between grading a student and checking whether they showed up to sit the exam.","l":0},{"t":"That binary shape is not an arbitrary design choice; it matches the shape of the thing being measured. Demand does not arrive in polite gradations at the moment of truth. Either a person reaches for the product and pays, or they nod warmly and do nothing, and the second outcome is indistinguishable from indifference no matter how encouraging the interview was. Andreessen's law and the CB Insights post-mortems are describing the same cliff edge from two directions. **A gate encodes the cliff instead of smoothing it into a gentle slope** on which a dead idea can be made to look survivable, one comforting decimal place at a time.","l":0}]},{"h":"How the matrix resolves","ps":[{"t":"The three lens states resolve into a single verdict through a fixed matrix, and the matrix reads D first, on purpose, before it will look at anything else. If D fails, the engine stops there and refuses to continue. The verdict is a hard pass, and feasibility and viability are never allowed to take the stand. **A failed desirability short-circuits the entire evaluation,** not as a punishment but as a plain consequence: there is nothing left for the other two lenses to be about. Asking whether a product no one wants can be built cheaply is not a harder question than it looks. It is a question with no meaning, and the engine declines to pretend otherwise.","l":0},{"t":"Only once D has cleared do the other two lenses begin to shape the outcome. D pass, F pass, V pass is a strong case: wanted, buildable, and financially sound, objectively worth backing, the rare deal where all three readings agree. If feasibility or viability is merely to-verify rather than outright failed, the verdict becomes conditional rather than a yes or a no. **The engine turns the unproven lens into a dated checkpoint** instead of forcing a premature verdict onto evidence that has not yet arrived. A conditional pass is an honest statement that the market is real and one execution question remains genuinely open.","l":1},{"t":"The order is not a convenience; it is the argument itself. Reading D first is precisely what stops a dazzling F and a spotless V from ever rescuing an absent market by the weight of their own numbers. The sequence hard-codes the hierarchy that Andreessen and the failure data both point at from opposite ends: **need is the precondition, not a co-equal vote,** and everything else is contingent on it clearing. Change the order and you change the conclusion. An engine that let feasibility speak first would be an engine optimized to fund well-built products that no one needs, which is the exact failure the matrix exists to prevent.","l":0}]},{"h":"Naming the specific death","ps":[{"t":"A cleared D with one failed lens is not a vague low score to be filed and forgotten. It is a specific, nameable death, and naming it precisely is most of the value the engine adds. **D pass with V fail is financially unviable:** people genuinely want the product, but the unit economics do not close at any honest price. The demand is real and the business still cannot survive its own cost structure, because every sale loses money and volume only deepens the hole. That is a verdict a founder can act on, redesign around, or walk away from with clear eyes, in a way that a bland 'below threshold' never permits.","l":0},{"t":"**D pass with F fail is technically blocked:** people want it, but it cannot yet be built at the quality or cost the promise requires. This is a fundamentally more hopeful failure than a dead D, and the difference matters enormously. When desirability is proven and feasibility is the wall, the market has already been de-risked; what remains is an engineering question, and engineering questions tend to resolve on a schedule that demand will patiently wait out. Many category-defining companies spent years technically blocked before the underlying capability caught up. None of them survived being unwanted.","l":0},{"t":"When D itself is only to-verify, the verdict is neither pass nor fail. It is keep going, and revisit the moment the signal actually arrives. This is exactly where the Startup Genome finding bites hardest: **74% of high-growth startups fail from scaling before product/market fit,** pouring feasibility and viability into a demand that no one has yet confirmed. They hired, built infrastructure, and bought growth on the assumption that D would show up later, and it did not. The engine refuses to let a company spend that way. Until desirability is real and evidenced, the correct action is to search, not to scale.","l":2}]},{"h":"Gate versus weighted average","ps":[{"t":"Naive scoring blends the three lenses into a single weighted average, and that blend is exactly where fatal deals hide. A dazzling feasibility and a pristine viability can average away a dead desirability, producing a comfortable middling number for a company that has no reason to exist. **The average launders the one flaw that kills,** turning a hard veto into a soft deduction. A 43% failure mode, the most common cause of death in the entire dataset, gets quietly diluted into a rounding error, and the deal clears review looking merely unremarkable rather than fundamentally doomed.","l":0},{"t":"A gate refuses that trade outright. It will not let strength in one dimension buy forgiveness in another, because the three dimensions are not fungible and were never meant to be traded against each other. Buildability and margin are real virtues, worth measuring and worth respecting, but **they are answers to a question that demand has to ask first.** An engine that lets them vote before D has cleared is not being generous or balanced. It is optimizing the efficient delivery of something no one ordered, which is the most expensive kind of excellence there is. The cost is not only the capital burned but the years of scarce talent spent building the wrong thing beautifully, when the same people could have found a real market instead.","l":1},{"t":"This is not pessimism; it is discipline. The engine stays honest about what a missing need actually means and declines to dress a hard pass up as a soft maybe to make the room feel better. Filled, half, and empty circles mark pass, to-verify, and fail, so **the verdict shows its full reasoning instead of hiding behind one blended figure.** Anyone can trace exactly which lens failed and why. The gate is not there to reject more deals for its own sake. It is there to refuse the one specific error that, across 431 post-mortems, killed more companies than any other.","l":0}]}]},{"meta":"8 min read · engine placement logic","standfirst":"The engine places a company by its evidence, not the round it names, then asks the one question that stage can actually answer.","stat":{"n":20,"unit":"%","label":"of the 2022 seed cohort graduated beyond seed, versus 51 to 61% in prior years","source":"Crunchbase News / Carta, 2024"},"sections":[{"h":"Evidence, not age","ps":[{"t":"The engine never places a company by how long it has existed or which round its deck claims. It places it by **what the evidence can support**. A team that closed a seed round two years ago but still has no repeatable way to win a customer is not a Series A read, whatever the paperwork says. The round name is a claim about maturity; the evidence is the only fact in the room, and the engine treats the two as different objects entirely. A label can be bought with a good narrative and a warm intro. Evidence cannot. So when the two disagree, the engine sides with the evidence every time, and lets the label fall where it may.","l":0},{"t":"This distinction is not pedantic. The three lenses of desirability, feasibility and viability do not soften or sharpen because a founder used a particular word on a slide. They respond to signal, and to nothing else. When a company arrives labelled Series A but carries only seed-stage proof, reading it at the label **flatters it into a score it has not earned**, and quietly imports expectations it was never built to meet. Reading it at the evidence is the harder and fairer act, because it refuses the story the label is trying to tell. The founder is not lying; they are optimistic, and optimism is exactly what a fair read is built to price correctly rather than punish.","l":0},{"t":"So the first move of any honest read is placement, not scoring. Before a single lens fires, the engine asks a narrow, unglamorous question: what has this company actually shown? Not what it plans, not what it projects, but what already exists as fact. The answer sets the altitude at which everything downstream is judged, and that altitude is not negotiable once set. **Get placement wrong and every score after it is precise about the wrong thing.** A beautifully calibrated Series A rubric applied to a pre-seed idea produces confident numbers that mean nothing, because they answer a question the company was never in a position to be asked.","l":1}]},{"h":"The bar rises each stage","ps":[{"t":"The same three lenses do not ask the same question forever. Desirability at pre-seed is a single sharp insight into a real and unmet pain, the kind a founder earns by living inside a problem. Desirability at scaling is a retention curve that survives paid acquisition, where the market votes with repeat behaviour rather than enthusiasm. **The lens is identical; the bar it holds up climbs** with the evidence a company should, by now, be able to show. What counts as a strong answer at one stage is a non-answer at the next. An articulate insight impresses at pre-seed and proves nothing at Series B, where only the cohort curves are allowed to speak.","l":0},{"t":"Feasibility follows the same escalation. Early on it asks whether the team can build the thing at all, and whether they have an earned reason to be the ones building it rather than anyone else. Later it asks whether the machine runs efficiently: whether each new customer costs less to win than they return, and whether that ratio improves or decays with scale. Viability moves from can this ever make money to **does the money already compound**. The questions harden because the company has had time and capital to produce harder proof, and a fair read expects the proof to have kept pace with the funding. Money buys evidence; the absence of evidence after money is itself a signal.","l":0},{"t":"This is why a read cannot be a fixed checklist. A checklist asks every company the same thing and rewards the one that happens to be furthest along, which is just a proxy for age dressed up as rigour. Calibrating the question to the stage does the opposite. It asks each company the question **its own evidence has made answerable**, and holds it to that answer rather than to an ideal it has no business meeting yet. The point is not to be lenient with young companies and strict with old ones. It is to ask, at every stage, the single question whose answer would actually change the decision, and to ignore the ones whose answers cannot yet exist.","l":1}]},{"h":"One fatal gap per stage","ps":[{"t":"Each stage carries exactly one gap that, if present, ends the read regardless of how strong everything else looks. At pre-seed the question is founder-market fit and a genuine pain, and the fatal gap is **a false need, or no reason this team should win**. If the pain is imagined or the founders have no earned edge, nothing else is worth evaluating, however polished the deck. At seed the question moves to a working product and first paid validation, and the gap is blunt: **nobody pays**, or the thing cannot actually be built. A prototype that demos well but that no one will part with money for has answered the desirability question in the negative, and no amount of roadmap redeems it.","l":0},{"t":"At Series A the question is product-market fit, retention and a repeatable acquisition motion, and the fatal gap is no PMF with collapsing retention: a leaky bucket that no new spend can fill. This is not a soft bar. CB Insights, reviewing 431 venture-backed shutdowns, found **poor product-market fit named in 43% of failures**, second only to running out of cash, which is usually the symptom rather than the cause. Tellingly, two-thirds of those PMF failures were early companies that never found a market at all, yet the fit question does not disappear at scale. Retention is where growth stories most often outrun the evidence, because spend can manufacture growth long after the product has stopped earning it.","l":1},{"t":"At Series B and scaling the question is unit economics, net revenue retention and efficient growth, and the fatal gap is structurally negative economics that scale only magnifies. The same CB Insights study put **unsustainable unit economics behind 19% of failures**, a quieter killer than a missing market but no less terminal. Late and pre-IPO, the question narrows again to the Rule of 40, cash flow and a credible path to profit, and the gap is the absence of that path. One gap per stage, and it is never the same gap twice. A company can clear every earlier bar and still die at the one its current stage puts in front of it, which is precisely why the read has to move with the company.","l":2}]},{"h":"The stage mismatch","ps":[{"t":"The classic error is a mismatch between the question asked and the stage in front of you, and it runs in both directions. Demand scale economics from a pre-seed team and you judge them on evidence they cannot possibly hold yet, **killing a real signal for the absence of one that was never due**. Forgive a scaling company its broken margins and you excuse the one gap that is now fatal, because the company still tells a charming early-stage story and the storyteller is persuasive. Both mistakes feel like discipline in the moment. The first feels rigorous; the second feels generous. Both are simply the wrong question asked at the wrong time, and both end in a decision the evidence never actually supported.","l":0},{"t":"The market makes this error at scale. Carta's data shows the seed-to-Series-A path has narrowed sharply: for the 2022 seed cohort **only about 20% had graduated beyond seed, against 51 to 61% in prior years**, with the median gap from seed to A now stretched past two years and only around half of a cohort reaching Series A even four years out. A great many of those stalled companies are not failures of ambition or effort. They are being asked a Series A question while sitting on seed-stage evidence, coming up short against a bar their stage never equipped them to clear, and mistaking a placement problem for a performance one.","l":0},{"t":"Both directions of the error share one root: reading the label instead of the evidence. A round name is a promise about maturity, and the engine treats every promise as **a hypothesis to test rather than a fact to accept**. Calibrated correctly, a thin pre-seed insight and a broken scaling margin are each measured against the bar that fits them, and neither is punished nor forgiven for the wrong reason. The discipline is symmetrical. It protects the young company from a bar it could not yet clear, and it refuses the mature company the early-stage grace it has quietly outgrown. Fairness in both directions is the same act, applied consistently.","l":1}]},{"h":"Calibration is the game","ps":[{"t":"Getting the stage right is what makes a read both fair and useful at once. It is fair because the company is measured against **what its own stage can prove**, not against an arbitrary ideal borrowed from a later one. A pre-seed team is not marked down for lacking a retention curve it had no time to grow; a scaling company is not let off for the same absence it has long since had the resources to fix. Each is held to its own bar, and only its own. Fairness here is not softness. It is the refusal to import a later stage's expectations into an earlier one, or an earlier stage's excuses into a later one.","l":0},{"t":"It is useful because the single gap the engine surfaces is **the gap that actually decides this company's next eighteen months**, not a distant worry or a question already settled. Telling a seed founder their unit economics are unproven is true and useless; nobody's are yet at that stage. Telling them nobody has paid twice is the whole game, because that is the wall they will actually hit. The value of a read is not how much it says, or how many risks it can list. It is whether it names the one thing that, if left unaddressed, ends the company, and says it clearly enough to act on.","l":1},{"t":"This is the quiet discipline underneath the three lenses. Evidence over age, a rising bar over a fixed one, one fatal gap held to its proper stage. **A read that skips placement is not a read; it is a guess wearing a score.** The lenses do not become wiser as a company matures, and they do not need to. The questions they are entitled to ask simply grow up alongside the company, getting harder in exact step with the evidence the company has had the time and money to produce. Place it right, ask the stage's own question, find the one gap that matters. Everything else is commentary.","l":0}]}]},{"meta":"8 min read · matching the verdict to the room","standfirst":"The verdict is not a grade. It is a match to the room already priced to buy your strongest lens, at the stage you are actually raising.","stat":{"n":4,"unit":" min","label":"is roughly all an investor spends on a first read of your deck (3 min 44 sec on average)","source":"DocSend / Harvard Business School (T. Eisenmann)"},"sections":[{"h":"A verdict is a match","ps":[{"t":"Most founders read a screening result as a report card: a number, a pass, a fail, a mark to feel proud or ashamed of. That framing is wrong at the root, because it assumes a single scale that everyone in the market agrees on. There is no single scale, and there never was one. Two competent investors can look at the identical deck and reach opposite conclusions without either of them making a mistake. The engine returns a verdict that **maps to a funding stage and to the investor type already built to want what you are strongest at** the heaviest. The output is a direction, not a rank, and reading it as a rank is the first and most expensive error a founder makes.","l":0},{"t":"Consider what the number is actually sitting against. A DocSend study conducted with Harvard Business School found that the average investor spends **three minutes and forty-four seconds** on the first read of a deck. That is not enough time to be argued out of a prior belief; it is only enough time to confirm or reject one. Whatever bias the reader walks in with will almost certainly be the bias they walk out with, because there is no room in two hundred seconds for a slow change of mind. So the verdict's real job is not to earn you a higher grade on some universal exam. It is to route your deck into the room whose bias already runs in your favor before the clock even starts ticking.","l":0},{"t":"The useful question is therefore never 'what score did I get.' It is **'which room is already built to want what I am strongest at.'** The engine answers that question first, because that single answer determines everything downstream of it: who you talk to, in what order you talk to them, which introduction you chase before the others, and which one piece of evidence you lead with in those decisive first four minutes. A grade tells you how you did on a test nobody agreed to sit. A match tells you where to walk. Only one of those two things moves a raise forward.","l":0}]},{"h":"No two rooms weigh alike","ps":[{"t":"The three lenses are Desirability, Feasibility, and Viability, and no investor on earth weights them equally. An angel writing a pre-seed check is buying conviction about a team and an insight, because that is all there is to buy yet. A growth fund is buying proven economics, because at its check size a story alone is uninvestable. The same startup can be a strong yes in the first room and an easy no in the second on the very same day, and **neither room is wrong** — they are pricing different things with different money on different clocks. Treat the disagreement as noise and you will chase the wrong doors for months.","l":0},{"t":"There is no universal scale because there is no universal buyer. Every investor type carries a mandate it did not choose freely, handed down by the shape of its own fund: **fund size, return math, and time horizon decide which lens it can afford to bet on**. A small fund that has to return capital on a handful of outsized wins must price conviction and asymmetry, because a merely good outcome does not move its fund. A large, late fund answerable to its own limited partners must price a model that already compounds, because at that scale it cannot afford a coin flip. The lens weighting is downstream of the check that pays for it, not downstream of taste or mood.","l":0},{"t":"This is exactly why a 'low' score is so often just a lens mismatch wearing the mask of a rejection. A team-and-insight startup scored by an economics-first room reads as weak, not because it is weak, but because it is **being measured on the axis it was never built to win yet**. Hand a pre-revenue company to a room that only knows how to price payback periods and cohort curves, and of course the number comes back thin. Read the verdict instead as a compatibility signal, and it stops feeling like a judgment on your worth and starts working as a filter on your calendar, which is the only thing it was ever meant to be.","l":0}]},{"h":"The weight shifts by stage","ps":[{"t":"Early rooms price the team and the insight, and almost nothing else. At pre-seed, accelerators, micro funds, and angels weight the lenses roughly **35 on Desirability, 45 on Feasibility, 20 on Viability**. Nobody has real revenue yet, so the economics lens is nearly discounted to zero; there is no unit economics to underwrite when there are no units. What carries the check at this stage is whether the team can actually build the thing they describe, and whether the underlying insight about the market is genuinely true rather than merely well-argued. Feasibility leads because execution risk is the risk that has not yet been retired.","l":1},{"t":"This is not folklore, and it is not a matter of one investor's taste. A Rebel Fund analysis of thousands of data points collected at Y Combinator Demo Day found a **weak-to-negligible correlation between early traction metrics and a company's valuation** — the early economics simply do not predict what the round ends up pricing. That single finding is the whole argument for why pre-seed rooms refuse to lead with the Viability lens. By the seed stage the weighting shifts toward the demand signal, landing near 45 on Desirability, 25 on Feasibility, 30 on Viability. The question moves from 'can they build it' to 'does anyone actually want it, and does that pull show up honestly in the data rather than in the pitch.'","l":0},{"t":"Then the ground tilts hard, and it tilts in one direction only. At Series A, multistage and sector funds weight the lenses roughly **25, 25, 50**, because the model now has to prove it compounds rather than merely exists. By the growth stage, growth-equity funds and family offices sit near **20 on Desirability, 20 on Feasibility, 60 on Viability**, which is almost entirely economics. Late money is not buying a story and has no patience for one; it is buying a machine whose unit economics already work at scale, and it prices you almost entirely on the single lens that the pre-seed room barely bothered to count. The lens that got you your first check is the lens your last check will ignore.","l":2}]},{"h":"Twelve rooms, one that fits","ps":[{"t":"Spread across those four stages sit roughly twelve distinct kinds of buyer, and each one prices a different combination of lens and stage. Pre-seed holds **angels, accelerators, and micro funds**, all leaning on team and insight. Seed adds institutional seed funds, thesis-driven sector specialists, and revenue-based financiers, each with its own tilt toward demand or early economics. Series A brings multistage firms, deep-sector specialists, and corporate venture arms, which start to demand proof the model scales. The growth stage brings growth equity, crossover funds, and family offices, which want the machine already running. Twelve doors, and behind each one a different weighting is already fixed before you ever knock. Knocking on all twelve with the same hand is not diligence; it is waste.","l":0},{"t":"The engine names the specific door whose mandate weights your strongest lens at the stage you are actually raising, rather than the stage you wish you were at. That match matters far more than another week of polishing slides. DocSend's data shows that a **cold, untargeted deck gets about two and a half minutes and rarely converts to a meeting, while a warm, well-targeted deck gets over four minutes** of attention and converts at a dramatically higher rate. The gap between those two outcomes is almost never the design of the slides. It is whether the deck landed in a room that was already inclined to say yes to the exact thing the company happens to be best at.","l":1},{"t":"This is the entire case for why fit-to-room beats spraying one deck at everyone with an email address. A pre-seed deck sent to a growth fund fails on economics it was never meant to have and could not possibly show. The identical deck sent to the room that prices team and insight can be a confident, immediate yes. Every wasted send also has a cost beyond the silence it earns: a pass from the wrong room can quietly sour a later warm introduction, and a scattered process signals to sharp investors that you do not understand your own stage. **Matching the room to your strongest lens is not gaming the process — it is refusing to be measured on the axis where you were always going to lose.**","l":0}]},{"h":"From fit to a path","ps":[{"t":"Knowing which room fits is only half of the value, and on its own it is a map without a route. A forward-motion layer converts that fit into something you can actually walk: **named institutions in the US and Taiwan to approach**, chosen because their mandate weights the lens you are strongest on at your current stage, together with a read on how each one tends to open a conversation and what it will want to see first. It is a map of directions to move and of people who would be worth an introduction, not a verdict read back to you in slightly different words. The point of the layer is to shorten the distance between a correct diagnosis and a booked first meeting.","l":1},{"t":"One line matters here more than anything else on the page, and it is not fine print to be skimmed: these named institutions are **directions to move and people to talk to, never an offer, solicitation, or guarantee of investment**. The engine points; it does not place capital, it does not speak for any fund, and it makes no promise whatsoever on any fund's behalf. Being named as a plausible fit is a suggestion about where your strengths might land well, and nothing more than that. What any room does with your deck once it arrives is entirely and only that room's decision to make.","l":2},{"t":"Put the two halves together and the discipline that falls out of it is unglamorous and simple. Read the verdict as a match rather than a mark, respect that the weighting genuinely moves with the stage rather than staying fixed, and spend your strictly finite outreach only on the doors already built to want your strongest lens. Your deck gets one first read of a few short minutes, and you rarely get a second. **The whole game is making sure those few minutes happen inside the one room where your strength is the exact thing being priced.** Everything else is noise dressed up as a score.","l":0}]}]},{"meta":"8 min read · the math the engine runs under a verdict","standfirst":"A wide band is not the model failing. It is the model refusing to lie about thin data.","stat":{"n":65,"unit":"%","label":"of US venture financings fail to return even 1x the capital invested; only 4% return more than 10x","source":"Correlation Ventures, analysis of 21,000+ financings, 2004–2013"},"sections":[{"h":"Why the math must be honest","ps":[{"t":"Correlation Ventures ran the numbers on more than twenty-one thousand financings and found that **65% failed to return even the capital that went in**, while a mere 4% returned ten times or more. Read that twice, because it breaks the intuition most spreadsheets are built on. This is not a bell curve with a spread around some average return. It is a power law: most outcomes cluster near zero and a thin, violent tail carries the entire result. In a distribution shaped like that, the average is a fiction that describes almost none of the actual outcomes. Any model that answers an early-stage question with one confident expected-return figure has already erased the only feature of the data that matters, and it did so on the first line.","l":2},{"t":"This is why the engine treats a single point estimate as **precision theatre**. A number like 3.2x return looks rigorous precisely because it hides its own uncertainty behind a decimal point. It reads as a measurement when it is really a guess wearing a lab coat, and the decimal is the coat. The deeper problem is that false precision is contagious. The moment you accept one over-confident number, every calculation downstream inherits a certainty the evidence never contained, and by the end of the model you are compounding guesses while believing you are compounding facts. A verdict built that way can be internally flawless and still be describing a company that does not exist.","l":2},{"t":"So the entire quantitative layer rests on one commitment: **honest ranges over false precision**. The engine would rather hand you a wide band it can defend than a sharp number it cannot, because a defensible range is a tool and an indefensible point is a trap. When the band comes back wide, that is not the math breaking down under pressure. It is the math reporting, faithfully, that the underlying evidence is thin, that the inputs disagree, or that the outcome genuinely could land in several very different places. The discipline is refusing to narrow that band just to look more decisive than the data allows, because looking decisive and being right are two entirely different jobs.","l":2}]},{"h":"Sizing without the fantasy","ps":[{"t":"The market slide is where most decks lie, and they rarely mean to. A top-down number starts from a trillion-dollar category, captures a plausible-sounding sliver of it, and lets the arithmetic do the persuading while nobody defends the sliver line by line. The problem is that the sliver is asserted, not earned. And the cost of that shortcut is not academic. CB Insights, reviewing the post-mortems of failed startups, found that **the single most common cause of death, present in 42% of cases, was building something with no real market need**. Top-down sizing is precisely the instrument that lets a founder skip the one check that would have caught it, because a percentage of an enormous total always feels large enough to be safe.","l":2},{"t":"So the engine refuses the top-down figure on its own terms and rebuilds the market from the ground up with a **Fermi estimate**: households times penetration times revenue per user times frequency. Each of those terms is a claim you can argue with, and that is the entire point of the exercise. A bottom-up build forces every optimistic assumption out into daylight where it can be named, questioned, and stress-tested one at a time, instead of letting it hide inside a single confident percentage. When a founder has to say out loud that thirty percent of households will adopt this and use it weekly, the number stops sounding inevitable and starts sounding like the specific, checkable bet it actually is.","l":2},{"t":"Then the engine lays the two estimates side by side and watches the gap. When bottom-up and top-down disagree by **more than three times**, that gap is not noise to be split down the middle, it is a broken assumption you have not located yet. Usually it hides in penetration or frequency, the two terms most easily dressed up as inevitability. **The three-times rule kills the hockey-stick fantasy** before it ever reaches a verdict, because a market that only exists top-down is a market the company has not yet found a real way to reach. The discipline is not to average the two numbers into a compromise, but to treat the disagreement itself as the finding and go hunt for what caused it.","l":2}]},{"h":"Returns as a distribution","ps":[{"t":"Because outcomes are fat-tailed, the engine models returns as a **Monte Carlo simulation** rather than a single figure. It begins with an explicit loss probability up front, an honest admission that most bets die, then draws the surviving outcomes from a **lognormal curve capped at 300x**, so that no one fantasy draw can quietly carry the entire average on its back. Thousands of runs later, it reads the resulting distribution at three points, P10, P50 and P90, plus the odds of a clean ten-times outcome. The cap is not a technicality. It is the model refusing to let a single imagined moonshot inflate the whole picture, which is exactly how an uncapped average lies about a portfolio that is mostly zeros.","l":2},{"t":"The base rates are what justify this pessimism, and they are brutal. Harvard's Shikhar Ghosh, studying more than two thousand venture-backed companies, found that **about 75% never returned cash to investors at all**, and that thirty to forty percent liquidated with a total loss. Set that against the Correlation Ventures tail and the shape sharpens: a model that reads only the P90, the dream outcome, is describing the 4% while pretending the 75% is not in the room. Reading the full distribution means the engine sees the graveyard as clearly as the lottery ticket, and weighs both in the same breath, which is the only honest way to price a bet where losing everything is the base case.","l":2},{"t":"This is why **the P10, the downside, is the honest number**. It is what happens when the story does not break your way, and it is the figure most decks never show, because it is the one that stings. If the engine cannot stomach the P10, the upside case does not get to speak louder simply because it is louder. A verdict that only survives at P90 is a bet on the tail dressed up as a plan, and the entire purpose of running the distribution is to know when that is all you actually have. The engine does not ban tail bets; plenty of great outcomes are exactly that. It just refuses to let one get quoted as a base case.","l":2}]},{"h":"Where the verdict is fragile","ps":[{"t":"A verdict that only holds under one exact set of inputs is a guess with good posture. So instead of defending its own conclusion, the engine attacks it, asking not whether the call is right but how easily it could be wrong. This inverts the usual instinct, which is to build the model until it produces the answer you were hoping for and then stop. Here the model is only trusted after it has been actively pushed until it breaks, because a conclusion that survives its own stress test is worth far more than one that was never tested. Two tools do that work, and both are designed to surface fragility rather than smooth it over into something that merely looks robust.","l":2},{"t":"The **sensitivity tornado** nudges each lens up and down two notches and ranks them by how far the verdict moves in response. The longest bar is your most fragile assumption, the single place where being slightly wrong flips the entire call from a yes to a no. That bar is not a weakness to be quietly smoothed over; it is a map, and arguably the most useful single output the whole engine produces. It tells you precisely what to go verify first, in the real world, with a customer or a contract or a cohort, before you waste another hour polishing the parts of the model that barely move the outcome no matter how wrong they are.","l":2},{"t":"Scenarios then rerun the whole verdict at **0.8, 1.0 and 1.15** for bear, base and bull. The spread between those three runs is the real output, not any one of them read alone. A tight spread means the call is genuinely about the company and would survive being slightly wrong about the inputs; a wide spread means the call is mostly about your assumptions all holding at once, which is a far more fragile thing to be right about. When that spread is wide, **the confidence mark drops to low on purpose**, and that is not a hedge. It is the honest report that the evidence, right now, cannot yet carry a stronger claim than that.","l":2}]},{"h":"A wide band is a signal","ps":[{"t":"Put the pieces together and one enemy runs through all of them: **precision theatre**, the habit of manufacturing certainty the data does not support. A confident TAM, a single expected return, a verdict quoted to two decimal places, a sensitivity ignored because it was inconvenient, they are all the same move, borrowing authority from a number the evidence never earned. The math in this engine is built specifically to refuse that move at every stage, from sizing the market to modeling the returns to stress-testing the call. It is easier to sound smart with a sharp wrong number than an honest wide one, which is exactly why the wide one is the harder and more valuable discipline.","l":2},{"t":"That refusal is not caution for its own sake, and it is not indecision. Read correctly, **a wide band is information**, often the most actionable information in the whole report. It tells a founder exactly where the story is still thin, which single assumption to go harden next, and how much of the current verdict is real signal versus optimism borrowed against a future that has not happened. A narrow band on thin data would tell you none of that. It would just feel reassuring while quietly pointing you at the 65% instead of the 4%, which is the most expensive kind of comfort there is.","l":2},{"t":"The engine's qualitative read and its quantitative layer are the same instinct expressed twice, in two different languages. The lenses say plainly what they see; the math says how sure the numbers actually allow anyone to be, and then refuses to round that certainty up to something more sellable. **Honest math is what earns the verdict its credibility**, because a model that will openly admit when it does not know is the only kind worth believing on the day it finally says that it does. Everything else is just a number with good posture, and the whole discipline is learning to tell the difference before you write the check.","l":2}]}]}],
  zh: [{"meta":"8 分鐘閱讀 · CB Insights、IDEO","standfirst":"一項耀眼的強項，往往正是體質虛弱的案子被放行的原因，所以引擎讓三個透鏡同時檢視，而且彼此看不到對方。","stat":{"n":42,"unit":"%","label":"在失敗新創的驗屍報告裡，最常被點名的死因是根本沒有市場需求","source":"CB Insights"},"sections":[{"h":"失敗只有三種","ps":[{"t":"多數篩選會把一家新創壓縮成單一結論，而判斷力就悄悄死在那個數字裡。一家公司從來不是單純的好或壞，它總是**在某一軸上強、在另一軸上脆弱**，而篩選的全部功課，就是看清楚強的是哪一軸、弱的又是哪一軸。混合分數刻意抹掉這個區別，它讓一個漂亮的九分，把一個致命的三分平均成一個舒服的六分，而舒服的六分，正是一家注定失敗的公司拿到會議機會的方式。三種不同的風險一旦被折進同一個數字，那個數字就不再告訴你任何能拿來行動的東西。","l":0},{"t":"這三個透鏡不是我們發明的。它來自 **IDEO 的 Tim Brown**，他把設計思考定義為尋找一個交集：人的需求、技術的可能性，以及生意本身的要求，三者重疊之處。IDEO 把它畫成三個交疊的圓，並把中間那一小塊稱為創新的甜蜜點。欲求性、可行性、存續性之所以配得上三軸的位置，理由很直接：它們就是**一家公司真正死去的三種方式**。沒人想要、沒人做得出來、帳永遠算不平。你這輩子會讀到的每一份驗屍報告，都是這三句話換上不同戲服後的樣子。","l":0},{"t":"混合結論之所以失效，是因為現實不會取平均。顧客不會有點想要一個沒人負擔得起去交付的產品，這門生意就是直接結束。**任何單一軸上的弱點，通常自己就足以致命**，不會被別處的強項稀釋掉，而這恰恰和取平均對一組數字所做的事完全相反。把三個透鏡分開讀，能讓每一種失敗方式一路清晰到做決定的那一刻。把它們讀成一個數字，則是讓一道致命裂縫被悄悄吸收進一個看起來體面的總分，也讓會議室裡的人，最後在爭論一個早已對不上眼前風險的分數。","l":0}]},{"h":"有沒有人要","ps":[{"t":"欲求性問的是最前面、也最不留情的問題：這個需求**是不是真實、尖銳、而且有足夠多人願意付錢**。不是點子聰不聰明，也不是 demo 漂不漂亮，而是有沒有一個真實的人，痛到願意改變他今天已經在做的事。多數創辦人真正倒下時，倒在的正是這道透鏡。在 CB Insights 對新創驗屍報告的分析裡，**沒有市場需求是被點名最多次的死因**，出現在大約四成二的案例中。最常見的死法，不是被別人做得更好或砸得更多，而是精心做出了一個根本沒人在等的東西。","l":0},{"t":"陷阱在於，欲求性是最容易騙過自己的一道透鏡。一場熱絡的 demo、幾個興奮的朋友、一份加入毫無成本的等候名單，全都讀起來像需求，卻全都不是。**可有可無的維他命，永遠輸給對方已經伸手去拿的止痛藥**，因為有更好要跟什麼都不做競爭，而多數時候贏的是後者。真正的檢驗，不在於人們嘴上說喜歡，而在於他們是否願意重新安排一段時間、或一筆預算來換取它。熱情既充沛又幾乎免費，改變過的行為卻稀缺而昂貴，而只有後者才算得上證據。","l":0},{"t":"這就是為什麼欲求性必須第一個讀、而且冷冷地讀。如果底層的需求虛弱，後面沒有任何一環救得回來。一支完美的工程團隊做出一個沒人要的東西，只是更快撞上牆；架在虛構市場上的漂亮商業模式，只是把這場虧損記錄得更精確。**這裡讀出來是冷的，就替上面的一切封了頂**，這也是為什麼一場認真的篩選，拒絕讓一支強團隊或一個聰明模式，把它說服成一份它並未掙得的溫度。需求要嘛存在、要嘛不存在，下游再多的優秀，都無權替這個問題投票。","l":0}]},{"h":"做不做得出來","ps":[{"t":"可行性問的是**這支團隊做得出這個機制、而且交得出來嗎**，不是理論上，而是用此刻在場的具體的人、技術與時間。投影片上說得通的產品，不等於做得出來的產品。真正的問題從來不是這種東西有沒有某個人在某個地方終究能做出來，而是這個具體計畫裡那個真正困難的環節，有沒有一條具體而可信的路，而且掌握在此刻提案的這群人手上。多數可行性風險，就藏在那一個難關裡，而多數提案都禮貌地繞過它，而不是穿過它。","l":1},{"t":"這裡的失敗比欲求性更隱微，因為它躲在能力後面。做得出一個產品九成的團隊，往往會假設最後那一成也會用同樣的方式擴展，然而那最後一成，通常才是整門生意的所在。**那個難關是承重的，其餘一切只是鷹架**。一場認真的可行性判讀，會把承重的那一塊單獨拉出來，要求證據證明正是這支團隊扛得起它：一個原型、一套過去出過貨的系統、一位確確實實解過同樣問題的人。路線圖上其餘的部分，都是有能力的團隊按預設就會完成的通用工作。","l":1},{"t":"在這一軸上，野心很廉價，能跑起來的機制才是唯一的貨幣。願景簡報用自信的文字描述終點，可行性卻完全只關心下一個困難的步驟，以及這一步到底有沒有真的踏出去。**一個能在真實輸入下存活的 demo**，重過一百張架構投影片，因為投影片假設難關已經解決，demo 卻證明了它。這道透鏡把一家公司和一篇文章區分開來。文章往往寫得更好，但只有公司真的跨過了那道原本會殺死它的具體鴻溝，而那一次跨越，正是可行性唯一在尋找的東西。","l":1}]},{"h":"帳算不算得平","ps":[{"t":"存續性問的是這個模式**能不能養活自己、讓事業活得長久**：賣出的每一個單位，是否都能回本再多賺一點，而這個優勢會隨時間複利累積，還是逐漸被磨平。一家公司可以既被真心喜愛、又真的做得出來，卻仍舊一單位一單位地失血而死，用九毛錢賣出一塊錢的價值，然後致命地想靠衝量把它補回來。這道透鏡是魅力用盡、算術接手的地方，也是創辦人最常拖延的一道，因為它最不討喜、也最難用一個好故事去掩飾。","l":2},{"t":"最常被引用的新創統計，是多數公司死於沒錢，CB Insights 把資金耗盡列在死因清單之首，出現在絕大多數的倒閉裡。但**沒錢是新創怎麼死的，不是為什麼死的**。資金會枯竭，是因為另外某一道透鏡早就破了：需求太薄、機制打滑，或單位經濟從來沒算平，每一筆銷售都在悄悄把坑挖得更深。存續性正是這些上游的弱點，最後以一個空掉的銀行帳戶現形的地方。誠實地讀它，意味著追問這些錢究竟買到了什麼，以及那份成本，有沒有哪一天真的往下彎。","l":2},{"t":"存續性也是一道獎勵耐心、懲罰一廂情願算術的透鏡。每一份計畫都能在試算表裡三年後轉盈，誠實的問題是：究竟哪一個具體的數字，一個成本、一條留存曲線、一個價格，必須移動、要移動多少，以及此刻有沒有任何真實的東西正在推它。**一條會複利的護城河，能把早期微薄的毛利變成一種必然**，一條會漏的，則把健康的毛利變成緩慢的衰退。差別不在這一季的數字裡，只在它們前進的方向裡，這也是為什麼存續性要看的，與其說是當下的數值，不如說是它的斜率。","l":2}]},{"h":"為何要盲讀","ps":[{"t":"接著是為什麼這一切都必須盲讀。人的判斷會被自己的第一印象汙染，這個偏誤由 Amos Tversky 與 Daniel Kahneman 在 1974 年命名：我們會先固定在一個初始值上，然後調整得遠遠不夠。給評審看一位在台上極具魅力的創辦人，他對技術、市場與財務的估計會一起往上飄，不是因為任何證據變了，而是因為**一個強烈訊號，會悄悄把周圍的一切都染上顏色**。在會議室裡，這不過就是動聽的故事替虛弱生意漂白的方式，而且它專門發生在那些會發誓自己很客觀的謹慎的人身上。","l":0},{"t":"所以引擎拒絕讓透鏡彼此交談。**每一軸由不同的評審獨立評分、看不到另外兩軸**，只依據跟自己那道問題相關的證據作業。負責欲求性的評審，永遠不會知道團隊是世界級的；負責存續性的評審，也永遠聽不到用戶有多愛這個產品。各自依自己的標準下判決，之後才把三者並排放在一起。回報很精準：某一軸再漂亮的答案，都不再能灌高其他軸，於是魅力四射的創辦人，仍得面對一場關於到底有沒有人想要的冷讀，被深愛的產品，仍得面對一場關於單位經濟的冷讀。**弱點會被看見，而不是被隔壁的強項吸收掉**。","l":0},{"t":"這樣讀，過了一個透鏡、甚至兩個，都不算過。有人想要卻做不出來的產品是空想，做得出來卻沒人要的產品是嗜好，有人要也做得出來、帳卻永遠算不平的產品，是一場緩慢而深受喜愛的破產。**一家新創必須同時跨過三軸**，因為現實也是同時考這三軸，三取其二，仍然是一次找了好藉口的失敗。三個盲讀出來的分數，買到的不是一張成績單，而是一份診斷：它說的不只是這家新創強不強，而是它究竟薄在哪裡、什麼事必須成真才補得起來。**低分的那一軸是一道問題，不是一紙否決**，它直接指向還沒做完的工作。","l":0}]}]},{"meta":"8 分鐘閱讀 · 引擎排序邏輯","standfirst":"面對同一份卷宗，專家的判斷可以差到五成五。引擎用一道順序回應這種雜訊：每一分都要證據撐住，每個透鏡先各自打分，最後才讓三者互相校正一次。","stat":{"n":55,"unit":"%","label":"兩位核保員替同一份案子報價的中位數差距","source":"Kahneman、Sibony、Sunstein《雜訊》(2021)"},"sections":[{"h":"判斷天生嘈雜","ps":[{"t":"問一整屋子的高階主管，兩位核保員替一模一樣的同一份案子報價，會差多少，他們說大概一成。真實的中位數差距是**五成五**。同一份卷宗，同一家公司，同一個下午，報價卻從大約九千美元擺盪到一萬六千美元，差別只在於它落到哪一張桌子上。身在其中的人完全看不見這種落差，這正是它危險的地方。那棟大樓裡沒有一個人覺得自己在猜，每位核保員都篤定、都資深，卻各自錯了不同的幅度。雜訊不是專家判斷的例外，而是它的預設狀態，一家大型保險公司每年為此付出數億美元，卻從來不會以某個誰都能指出來、能修正的明顯錯誤現身。","l":0},{"t":"這不是一個關於保險的故事。只要有人憑整體印象形成一個判斷、再把它當成決策，各行各業都是這副模樣。一個靠感覺評出來的新創，是一枚你看不見偏差的硬幣：同一份簡報，同一個人在兩個不同的早晨讀，會給出兩個不同的判決，而且他會用一樣的信念替兩個判決辯護。**問題從來不是智力不足，而是缺一套固定的程序**。才華不會消除雜訊，只會讓雜訊變得更有自信，而一個有自信的錯誤數字，遠比一個猶豫的數字更難反駁，因為那份自信會被誤認成證據。","l":0},{"t":"解方不是換一個更聰明的評審。跨越 136 項研究，機械式、有規則的預測，勝過專家臨場判斷的次數比落敗多出約**一成**，而且幾乎不會明顯更差，這個結果在各種任務、各種資歷之間都站得住。引擎從這裡得到的教訓很直白：**結構勝過直覺，不是因為它更聰明，而是因為它一致**。所以引擎拒絕形成單一印象，它強加一道順序：先閘住證據，再讓每個透鏡各自打分，最後只讓它們互相校正一次。順序本身就是紀律，而紀律正是在雜訊抵達任何一個分數之前，就把它抽乾的東西。","l":1}]},{"h":"證據決定分數","ps":[{"t":"多數人看一個案子，是先聽到一個故事，再回頭去找能替故事加分的數字。引擎把這個順序反過來。任何維度開始評分之前，它會把創辦人的每一項主張拆成三堆：**已知**、**缺漏**，以及還需要查證的。分數只建立在第一堆上。一段關於市場的生動描述，不是市場存在的證據，而是一個關於市場的假設，它會待在第二堆裡，直到有真實的東西出現、把它挪動為止。一項主張落在哪一堆，是在任何人去看它講得多動聽之前，就先決定好的，這代表一個安靜、手上有證據的創辦人，排名會勝過一個口才絕佳、卻兩手空空的說書人。","l":0},{"t":"接著是真正撐住整套流程的那條規則：任何未經證實的主張，**上限只給三分**。創辦人可以用最流利的語言描述市場、技術優勢或回本曲線，在證據落地之前，這個維度就是爬不過三分。這一條，就是讓分數無法被話術拉高的關鍵。流利不等於牽引力，自信不等於一群真實的用戶。一封簽了字的意向書，價值大過一百張描述它所代表需求的投影片。天花板一直壓著，直到一個事實把它抬起來，而再多的口才都不算一個事實。","l":0},{"t":"效果安靜卻決定性。自信、包裝、敘事的推進力，這些正是能贏得全場的東西，本身卻不帶任何分量。七分之所以是七分，是因為紀錄撐得住，而被封在三分與真正掙到七分之間的落差，剛好就是創辦人還沒補完的功課，而且是以一個數字、而非一種氛圍寫下來的。雜訊也在這裡被抽乾：引擎**拒絕替說服力定價**，就把兩個誠實的讀者原本會差到**五成五**的那塊空間，直接抹掉。兩個評審讀著同一批證據、套著同一道上限，落點就會落在同一個地方。","l":1}]},{"h":"每個透鏡各自打分","ps":[{"t":"三個透鏡各自獨立評分，這個順序不是形式。如果欲求性、可行性、存續性放在一起評，一個強訊號就會滲進其他兩者：漂亮的產品會誘人假設它的經濟模型一定成立，名氣大的創辦人會讓市場看起來勢在必得。心理學稱這叫**月暈效應**：一個壓倒性的印象，會悄悄替其他每一個判斷上色，而這正是讓兩個看著同一批事實的人，差出五成五的那具機器。你最先注意到的那件事，會變成你不自覺拿來解讀其他一切的透鏡。","l":0},{"t":"所以每個透鏡只回答自己那一題，誰也不能向別人借信用。欲求性問的是有沒有人真的需要這東西。可行性問的是這支團隊能不能真的做出來並交付。存續性問的是東西做出來之後撐不撐得住。**分開問，每一題都答得出來；混在一起，三題就變成一種情緒**。名氣大的創辦人不會讓市場變成真的，優雅的 demo 也不會讓單位經濟自己成立。獨立，就是不讓這些事實彼此滲漏，好讓某一題的強答案，永遠不會變成下一題借來的答案。","l":2},{"t":"各自打分還有一個更深的理由。月暈效應不只會灌水一個弱透鏡，它還會把灌水藏起來，因為讀的人根本沒把借來的信用看成借來的。**一個你拆不開的分數，就是一個你信不過的分數**。在三個透鏡碰面之前，先讓每一個對著自己的證據打分，是事後唯一能弄清楚究竟哪一個透鏡撐起了判決、哪一個只是偷偷搭了別人便車的辦法。獨立不是透鏡之間的客套，而是一條稽核軌跡，而稽核軌跡正是讓你幾個月後能重新打開一個決定、看清它當初為什麼被做出來的東西。","l":1}]},{"h":"淘汰不是平均","ps":[{"t":"在任何加總之前，先套用淘汰條件。致命傷會直接終結這次評讀，而不是被平均稀釋掉。如果一個案子違法、結構上根本募不到資、或者依賴一個不存在的市場，別處再強也贖不回它。**一個零，應該讓判決崩塌，而不是被沖淡**，而平均在物理上就無法表達這件事。三個七分配一個零，平均出來是舒服的五分多，而這剛好就是那個讓一家注定失敗的公司拿到錢的安心數字。淘汰先跑，致命傷就沒有機會躲進一個平均值裡面。","l":0},{"t":"這就是為什麼天真的平均會作為方法失效。把三個透鏡揉成一個數字，剛好把案子最脆弱的地方藏起來，也讓一個強透鏡默默替一個壞掉的透鏡補貼。**平均不是嚴謹，而是嚴謹的戲服**。它生出一個乾淨的單一數字，感覺很客觀，卻抹掉了唯一要緊的區別：這個弱點，是一道能補起來的缺口，還是一堵會撞上去的牆。漂亮的數字，是誠實判讀的敵人，因為工整正是真實風險第一個摧毀的東西，而一套把風險抹平的方法，優化的是舒適，不是真相。","l":0},{"t":"獨立讓破綻留在檯面上，而只有留得住的破綻才值得動手。當每個透鏡都自己站著，一個低分就會指向某件具體的事：一個沒人急著要的需求，一個這支團隊做不出來的東西，一個規模一放大就漏錢的模型。**你沒辦法修一個平均，但你可以修一個透鏡**。把三個分數一路分開到最後，就是把一紙判決，變成一張待辦清單，而不是一只隨心情變色的戒指，而待辦清單才是創辦人真正用得上的輸出。一個揉在一起的分數只叫你感到擔憂，一個分開的分數告訴你該去哪裡動工。","l":2}]},{"h":"再走一輪交叉","ps":[{"t":"唯有在獨立分數定案之後，透鏡才開始彼此校正，每個方向只修一次，總共六個方向：D 修 F、D 修 V、F 修 D、F 修 V、V 修 D、V 修 F，任一方向最多一格。透鏡之間確實會互相提供資訊，假裝不會，本身就是另一種扭曲。**一個真實而急迫的需求，可以正當化更硬的技術投入**，而薄弱的經濟模型，也應該拖累一個原本優雅的產品。這一輪是真的，但它有邊界，而邊界正是允許它存在的全部理由。一格，足以登記一個真實的關聯，又小到不讓月暈從側門溜回來。","l":0},{"t":"把一強一弱的組合擺在一起讀，判決才長出鋒利的邊。強 D 配弱 F，是**對的需求，錯的時機**。強 F 配弱 V，做得出來，卻撐不過自己經濟模型的碰撞。強 V 配弱 D，是替一個沒人急著要的需求，算了一張漂亮的試算表。交叉這一輪，讓引擎不只能說一個案子有多好，還能說它錯的時候，究竟是哪一種錯，而這才是創辦人動得了手的診斷。一個揉在一起的單一分數永遠做不出這個區別，因為它早就把形狀丟掉了。","l":1},{"t":"這就是勝過憑感覺整體判讀的紀律。整體一瞥把所有東西一次攪在一起，稱之為直覺；天真的平均把所有東西攪在一起，稱之為嚴謹。兩者都丟掉了那個能告訴你公司會在哪裡斷掉的結構。**先各自獨立，再走一輪有邊界的交叉校正，兩樣一次給你**：一個信得過的分數，因為沒有任何東西是被話術抬上去的；和一個能動手的診斷，因為沒有任何東西是被平均抹掉的。這就是一個數字和一個決定之間的差別，也正是這道順序為什麼要被固定、而不是交給感覺的全部理由。順序不是官僚，它是唯一擋在一個判決與一場五成五擲硬幣之間的東西。","l":2}]}]},{"meta":"8 分鐘閱讀 · 三元裁決矩陣","standfirst":"三個透鏡，卻不是三張等值的票。欲求性是那道門：沒人需要，做得再好、定價再對，都買不回這筆案子。","stat":{"n":43,"unit":"%","label":"倒閉新創死於 PMF 不成立：市場根本不要他們做出來的東西","source":"CB Insights, 2024（431 家創投背景公司驗屍報告）"},"sections":[{"h":"需求先於一切決定","ps":[{"t":"當 CB Insights 讀完 431 家在 2023 年後倒閉的創投背景公司的驗屍報告，真正該讓任何投資人停下來的，不是那 70% 資金耗盡的比例。資金耗盡是創業怎麼死，幾乎從來不是為什麼死。真正的原因藏在現金底下的那一層：**有 43% 是因為市場根本不要他們做出來的東西。** 資金是看得見的症狀，是最後一個停止跳動的生命徵象。需求的缺席才是底下那個病，而且是桌上最常見的一種。一家公司可以募得漂亮、花得自律，最後仍在為一個永遠不會出現的顧客而打造。銀行餘額只告訴你這場搜尋何時結束，不告訴你它為什麼從一開始就注定失敗。","l":0},{"t":"Andreessen 在 2007 年那篇首度讓 product/market fit 這組詞進入流通的文章裡，講的是同一件事。他的說法刻意地直白：**市場是決定一家新創成敗最重要的因素。** 好團隊遇上爛市場，市場贏；爛團隊遇上好市場，市場還是贏。一個真實的市場，幾乎不管執筆的是誰，都會把產品從公司裡拉出來，因為未被滿足的需求是一個真空，總會有東西衝進去填補。死掉的市場則相反：它會吸走任何份量的才華、資本與工藝，卻什麼都不回報，因為根本沒有真空等著產品去填。","l":0},{"t":"這就是為什麼一套評案引擎不能把欲求性當成與另外兩者並列的一種偏好。可行性與存續性問的都是執行：這東西造不造得出來，造出來之後數字算不算得平。兩者都默默假設交易的另一端已經站著一個買家。**一旦這個假設是假的，後面每一個答案都在極其精準、卻完全無關地回答錯的問題。** 你評的不再是一筆或許還能被補強的弱案，而是一場被打扮成公司的、根本沒發生的事：附上一份簡報、一張財務模型，和一條指向沒人想抵達之處的路線圖。世上最自律的執行，也救不了一個從一開始就空掉的前提，再多針對「怎麼做」的盡職調查，都翻不出一個完全活在「到底要不要」裡的問題。","l":0}]},{"h":"為何欲求性是門","ps":[{"t":"沒人要的產品不是一筆差投資，而是根本不算投資，因為沒有一個底層資產能讓錢附著上去。你可以把它做到零瑕疵、定價到健康的毛利、配上你找得到最強的操盤手，最後手上握的仍是一整倉世界不會伸手去拿的東西。其餘每一項優點都是真的，也都是白費。**欲求性是唯一能把另外兩個透鏡歸零的透鏡，** 因為只有它決定另外兩者所描述的東西到底存不存在。可行性與存續性衡量的是產品的種種性質；欲求性衡量的，是這個產品到底有沒有被衡量的理由。","l":0},{"t":"所以引擎不把欲求性揉進平均，而是把它當成一道門，而門的行為和權重根本不同。權重永遠可以被補償：這裡低分，被那裡的高分悄悄抵掉，混合之後就把缺口藏了起來。門拒絕這種算術。**你要嘛過了，要嘛沒過，** 門後再多的才華，都不會把你拉回門前。門問的不是有多少，而是到底有沒有。這是替一個學生打分數，和確認他到底有沒有來坐進考場，兩者之間的差別。","l":0},{"t":"這種二元的形狀不是隨意的設計選擇，它對上的正是被衡量之物本身的形狀。到了關鍵時刻，需求不會客氣地分成一格一格的深淺。人們要嘛伸手掏錢，要嘛熱絡地點頭卻什麼都不做，而後者無論訪談當下多讓人振奮，都和冷漠無法區分。Andreessen 的定律和 CB Insights 的驗屍報告，是從兩個方向描述同一道懸崖。**門把這道懸崖直接編碼進來，而不是把它抹平成一道和緩的斜坡，** 好讓一個已死的點子，靠著一位又一位安慰人的小數點，被弄得看起來還能活。","l":0}]},{"h":"矩陣如何收斂","ps":[{"t":"三個透鏡的狀態透過一張固定矩陣收斂成單一裁決，而矩陣刻意先讀欲求性，先於它願意去看任何其他東西。若欲求性不過關，引擎就停在那裡，拒絕再往下走。裁決是直接否決，可行性與存續性永遠沒有上台作證的機會。**欲求性一旦失守，整場評估直接短路，** 這不是懲罰，而是單純的結果：已經沒有東西可供另外兩個透鏡去描述。問一個沒人要的產品能不能被便宜地造出來，並不是一個比表面看來更難的問題，而是一個沒有意義的問題，引擎拒絕假裝它有意義。","l":0},{"t":"唯有欲求性過關，後兩個透鏡才開始塑形結果。欲求性、可行性、存續性三者皆過，是強案：有人要、造得出、財務穩健，客觀值得支持，是三個讀數難得一致的那種案子。若可行性或存續性只是待驗證，而非直接不適合，裁決便從是或否，轉成有條件。**引擎把那個尚未證實的透鏡轉成一個有期限的檢核點，** 而不是硬把裁決套到還沒到位的證據上。一個有條件的過關，是一句誠實的話：市場是真的，還有一個執行問題確實懸而未決。","l":1},{"t":"這個順序不是為了方便，它本身就是論點。先讀欲求性，正是為了擋住再耀眼的可行性、再乾淨的存續性，靠自己的數字份量去搶救一個不存在的市場。這道次序把 Andreessen 與失敗數據從兩端共同指向的階層硬寫進來：**需求是前提，不是等值的一票，** 其餘一切都以它過關為條件。換掉順序，就換掉結論。一套讓可行性先發言的引擎，會是一套被最佳化來資助「做得很好卻沒人需要」之產品的引擎，而那正是這張矩陣存在要防的那種失敗。","l":0}]},{"h":"為死法指名","ps":[{"t":"欲求性過關卻有一個透鏡失守，不是一個含糊的低分，供人歸檔遺忘。它是一種可以指名的死法，而精準地指名，就是引擎所加上的大半價值。**欲求性過、存續性不過，是財務不成立：** 有人是真的要，但在任何誠實的價格下，單位經濟都算不平。需求是真的，生意卻仍然撐不過自己的成本結構，因為每賣一筆就虧一筆，量越大，坑越深。這是一個創辦人能據以行動、能重新設計、能睜著眼睛走開的裁決，而一句平板的「未達門檻」永遠給不了這些。","l":0},{"t":"**欲求性過、可行性不過，是技術受阻：** 有人要，但目前還造不到承諾所要求的品質或成本。這是一種比欲求性死掉樂觀得多的失敗，而這個差別極其重要。當欲求性已被證明、可行性才是那面牆，市場其實已經去風險化了，剩下的是一個工程問題，而工程問題往往會照一個需求願意耐心等下去的時間表解決。許多定義整個品類的公司，都曾在底層能力追上來之前，技術受阻多年。但沒有一家，撐得過「沒人要」。","l":0},{"t":"若連欲求性本身都只是待驗證，裁決就既不是過也不是否，而是繼續走，一等到訊號真正出現就回頭看。Startup Genome 的發現，正是在這裡咬得最深：**74% 的高成長新創，死於在找到 PMF 之前就急著擴張，** 把可行性與存續性倒進一個沒人確認過的需求裡。他們招人、建基礎設施、花錢買成長，全押在欲求性稍後會出現的假設上，結果它沒有。引擎拒絕讓一家公司這樣花錢。在欲求性成為真的、有證據之前，正確的動作是搜尋，不是擴張。","l":2}]},{"h":"門與加權平均","ps":[{"t":"粗糙的評分把三個透鏡揉成單一的加權平均，而那個混合，恰恰是致命案子藏身之處。耀眼的可行性配上乾淨的存續性，可以把一個早已死去的欲求性平均掉，替一家沒有存在理由的公司算出一個令人安心的中庸數字。**平均，正好洗白了那個會致命的缺陷，** 把一道硬否決，變成一筆軟扣分。一個 43% 的失敗模式，整份資料裡最常見的死因，就這樣被悄悄稀釋成無關緊要的零頭，於是這筆案子通過了審查，看起來只是平平無奇，而不是根本注定失敗。","l":0},{"t":"門徹底拒絕這種交易。它不容許某一維度的強項去換取另一維度的赦免，因為這三個維度並不可互換，本來就不該拿來彼此對沖。造得出來與有毛利都是真的優點，值得衡量、值得尊重，**但它們回答的，是一個需求必須先問的問題。** 一套讓它們在欲求性過關之前就投票的引擎，並不是在寬厚或在求平衡，而是在把沒人下單的東西送得更有效率，那是所有卓越裡最昂貴的一種。代價不只是燒掉的資本，還有把稀缺的人才耗在「把錯的東西做得很漂亮」上的那些年，而同一批人，本來可以去找到一個真實的市場。","l":1},{"t":"這不是悲觀，而是紀律。引擎對「缺了需求」到底意味著什麼保持誠實，拒絕為了讓會議室好過一點，就把直接否決打扮成一個溫和的也許。實心、半實心與空心圓分別代表過關、待驗證與不適合，**讓裁決攤開自己完整的推理，而不是躲在一個混成的數字後面。** 任何人都能追出到底是哪個透鏡失守、為什麼失守。這道門的存在，不是為了否決更多案子本身，而是為了拒絕那一個特定的錯誤：在 431 份驗屍報告裡，它殺死的公司比任何其他原因都多。","l":0}]}]},{"meta":"8 分鐘閱讀 · 引擎定位邏輯","standfirst":"引擎用證據而非輪次來定位一家公司，再問這個階段真正答得出來的那一個問題。","stat":{"n":20,"unit":"%","label":"2022 年種子輪世代僅此比例走過種子階段，過去為 51% 至 61%","source":"Crunchbase News／Carta，2024"},"sections":[{"h":"看證據不看年資","ps":[{"t":"引擎從不用一家公司成立多久、或簡報自稱哪一輪來定位它，而是看**證據撐得起什麼**。兩年前結束種子輪、至今卻沒有可複製獲客方式的團隊，無論文件怎麼寫，都不是 A 輪的判讀。輪次名稱是一種關於成熟度的宣稱，證據才是這個房間裡唯一的事實，引擎把兩者當成完全不同的東西看待。標籤可以靠一個漂亮的敘事與一次熱情的引薦換來，證據不行。所以當兩者相互矛盾，引擎每一次都站在證據這一邊，讓標籤自己去找它該落的位置。","l":0},{"t":"這個區分並不是咬文嚼字。欲求性、可行性、存續性這三個透鏡，不會因為創辦人在投影片上用了某個詞就變軟或變硬，它們只回應訊號，別的一概不理。當一家公司頂著 A 輪的標籤出現、手上卻只有種子階段的證明，照著標籤讀，就是把它**美化成一個它沒有掙來的分數**，並悄悄把它根本無力承擔的期待也一併帶了進來。照著證據讀，才是那個比較難、也比較公平的動作，因為它拒絕了標籤想說的那個故事。創辦人並沒有說謊，他只是樂觀，而樂觀正是一次公平判讀該去正確定價的東西，而不是拿來懲罰的把柄。","l":0},{"t":"所以任何誠實判讀的第一步是定位，而不是評分。在任何一個透鏡啟動之前，引擎先問一個很窄、也不起眼的問題：這家公司實際上拿出了什麼。不是它計畫什麼，也不是它預測什麼，而是已經作為事實存在的東西。這個答案決定了後面一切被評判的高度，而這個高度一旦定下就不容再議。**定位錯了，之後每一個分數都只是把錯的東西算得很精準。**把一套精雕細琢的 A 輪評分標準，套在一個種子前的點子上，只會產出一堆自信卻毫無意義的數字，因為它們回答的，是一個這家公司根本還沒資格被問的問題。","l":1}]},{"h":"標準逐階升高","ps":[{"t":"同樣三個透鏡，不會永遠問同一個問題。欲求性在種子前，是對一個真實而未被滿足的痛點的一個銳利洞察，那是創辦人靠著活在問題裡才掙得來的；欲求性到了規模階段，是一條在付費獲客之下依然撐得住的留存曲線，此時市場用重複行為投票，而不是靠一時的熱情。**透鏡完全相同，它舉起來的標準卻在攀升**，隨著一家公司此刻理應能拿出的證據而升高。在某一階段算是好答案的東西，到了下一階段就是沒有答案。一個講得很漂亮的洞察，在種子前令人印象深刻，到了 B 輪卻證明不了任何事，因為那裡只有世代留存曲線有資格說話。","l":0},{"t":"可行性也走同樣的升級。早期它問的是團隊到底做不做得出來、以及他們有沒有比任何人都更該做這件事的理由。後期它問的是這台機器跑得有沒有效率：贏得每一個新客戶的成本，是不是低於他們帶回來的價值，而這個比率會隨規模改善還是惡化。存續性則從這門生意究竟能不能賺錢，走到**錢是不是已經在複利**。問題之所以變硬，是因為公司已經有時間與資金去產出更硬的證明，而一次公平的判讀，會期待證明跟得上募到的錢。錢買得到證據，拿了錢之後卻仍然沒有證據，本身就是一個訊號。","l":0},{"t":"這正是為什麼判讀不能是一張固定的檢查表。檢查表問每一家公司同一件事，然後獎勵那個剛好走得最遠的，而走得多遠不過是年資的代名詞，只是被打扮成了嚴謹。把問題校準到階段做的是相反的事。它問每一家公司那個**它自己的證據已經有能力回答的問題**，並用這個答案來衡量它，而不是拿一個它此刻根本沒資格達到的理想來要求。重點不是對年輕公司寬容、對成熟公司嚴格，而是在每一個階段，都去問那個答案真的會改變決策的唯一問題，並忽略掉那些答案此刻還不可能存在的問題。","l":1}]},{"h":"每階段一個死穴","ps":[{"t":"每個階段都恰好帶著一個缺口，一旦存在，無論其他地方看起來多強，判讀都到此為止。種子前問的是創辦人與市場的契合以及一個真實的痛點，致命缺口是**假需求，或這支團隊沒有非贏不可的理由**。如果痛點是想像出來的、或創辦人沒有掙來的優勢，其他一切都不值得評估，簡報再精美也一樣。到了種子輪，問題移到可運作的產品與第一筆付費驗證，缺口很直白：**沒有人付錢**，或這個東西根本做不出來。一個示範起來很好看、卻沒有人願意為它掏錢的原型，已經對欲求性這個問題給出了否定的答案，再多的產品路線圖也救不回來。","l":0},{"t":"A 輪問的是產品市場契合、留存，以及可複製的獲客模式，致命缺口是沒有 PMF 加上留存崩塌：一個再多新投入都填不滿的漏桶。這不是一道好過的關。CB Insights 檢視 431 家倒閉的創投背景公司，發現**產品市場契合不佳出現在 43% 的失敗案例中**，僅次於資金耗盡，而資金耗盡通常是症狀而非病因。值得注意的是，其中三分之二的 PMF 失敗，是從未找到市場的早期公司，但契合這個問題並不會到了規模階段就消失。留存正是成長故事最常跑在證據前面的地方，因為在產品早已不再自己賺得成長之後，投入的錢仍能製造出成長的假象。","l":1},{"t":"B 輪與規模階段，問的是單位經濟、NRR 與有效率的成長，致命缺口是規模只會放大的結構性為負經濟。同一份 CB Insights 研究把**單位經濟不可持續列為 19% 失敗的背後原因**，它比缺市場更安靜，卻同樣致命。到了後期與上市前，問題再次收斂到 Rule of 40、現金流與一條可信的獲利路徑，而缺口就是這條路的不存在。每個階段一個缺口，而且從來不會是同一個。一家公司可以跨過先前每一道門檻，卻仍然死在它現階段擺在面前的那一道，這正是為什麼判讀必須跟著公司一起移動。","l":2}]},{"h":"階段錯配","ps":[{"t":"典型的錯誤，是問出來的問題與眼前的階段對不上，而且會朝兩個方向發生。向種子前團隊索求規模經濟，就是用他們此刻不可能握有的證據去評判他們，**為了一個本來就還沒到期的缺口，扼殺一個真實訊號**。原諒規模階段公司破掉的毛利，則是替它放過此刻已經致命的那個缺口，只因為這家公司還在講一個動聽的早期故事，而說故事的人很有說服力。兩種錯誤當下都像是一種紀律。前者顯得嚴謹，後者顯得寬厚。但兩者都不過是在錯的時間問了錯的問題，也都以一個證據其實從未支持的決策告終。","l":0},{"t":"市場正在大規模犯這個錯。Carta 的數據顯示，從種子到 A 輪的路已明顯收窄：2022 年的種子輪世代裡，**只有大約 20% 走過了種子階段，而過去這個數字是 51% 到 61%**，種子到 A 的中位間隔如今已拉長到超過兩年，即使給滿四年，也只有約一半的世代能走到 A 輪。那一大批卡住的公司，很多並不是野心或努力的失敗。它們是在只有種子階段證據時，被問了一個 A 輪的問題，於是在一道它們的階段從未讓它們有能力跨過的門檻前落了空，把一個定位的問題，誤當成了表現的問題。","l":0},{"t":"兩個方向的錯誤共用同一個根源：讀標籤而不讀證據。輪次名稱是一個關於成熟度的承諾，引擎把每一個承諾都當成**待驗證的假設，而不是照單全收的事實**。校準對了，一個薄弱的種子前洞察與一條破掉的規模階段毛利，各自對照適合自己的標準被衡量，不會因為錯誤的理由被懲罰，也不會被原諒。這份紀律是對稱的。它保護年輕公司不被一道它還跨不過的門檻打倒，也拒絕給成熟公司那份它早已不該再享有的早期寬容。兩個方向上的公平，其實是同一個動作，只是被一致地施行。","l":1}]},{"h":"校準即全部","ps":[{"t":"把階段判對，是讓一次判讀同時做到公平與有用的關鍵。公平，是因為公司被拿來對照的，是**它自己這個階段證明得了的東西**，而不是一個從後面某個階段借來的憑空理想。種子前團隊不會因為沒有一條它根本沒時間長出來的留存曲線而被扣分；規模階段公司也不會因為同樣的缺席而被放過，畢竟它早已有資源去補上。各自對照自己的標準，而且只對照自己的。這裡的公平不是心軟，而是拒絕把後一階段的期待搬進前一階段，也拒絕把前一階段的藉口搬進後一階段。","l":0},{"t":"有用，是因為引擎浮現的那一個缺口，是**真正決定這家公司未來十八個月的那個缺口**，而不是遙遠的隱憂或早已定案的問題。告訴一個種子輪創辦人他的單位經濟還沒被證明，這句話為真，卻毫無用處，因為在那個階段沒有人的單位經濟被證明了。告訴他還沒有人付第二次錢，才是全部的重點，因為那才是他真正會撞上的那道牆。一次判讀的價值不在於它說了多少、能列出多少風險，而在於它有沒有點出那一件一旦不處理就會終結公司的事，並說得夠清楚、清楚到可以據以行動。","l":1},{"t":"這就是三個透鏡底下那份安靜的紀律。證據勝過年資，升高的標準勝過固定的標準，一個致命缺口對照它該有的階段。**跳過定位的判讀不是判讀，是一個披著分數的猜測。**透鏡不會隨著公司成熟而變聰明，它們也不需要。只是它們有資格問的那些問題，會隨著公司一起長大，硬度剛好跟著公司有時間與金錢產出的證據同步遞增。定位對，問這個階段自己的問題，找出那唯一重要的缺口。其餘的一切，都只是註腳。","l":0}]}]},{"meta":"8 分鐘閱讀 · 把裁決對應到對的房間","standfirst":"裁決不是分數，而是把你配對到那間早已願意為你最強透鏡買單、又正好落在你此刻募資階段的房間。","stat":{"n":4,"unit":" 分鐘","label":"就是投資人第一次讀你簡報大約花的全部時間（平均 3 分 44 秒）","source":"DocSend／哈佛商學院（T. Eisenmann）"},"sections":[{"h":"裁決是一場配對","ps":[{"t":"多數創辦人把篩選結果讀成一張成績單：一個數字、一個過、一個不過，一個值得驕傲或羞愧的印記。這個框架從根上就是錯的，因為它假設市場裡存在一把大家都認可的尺，但這把尺並不存在，也從來沒有存在過。兩位同樣稱職的投資人，可以看著同一份簡報得出完全相反的結論，而兩人都沒有犯錯。引擎給出的裁決，是**對應到一個募資階段，以及那一類最看重你最擅長之處的投資人**。它給的是方向，不是名次，而把它讀成名次，是創辦人會犯的第一個、也是最昂貴的錯。","l":0},{"t":"先看清這個數字對照的是什麼。DocSend 與哈佛商學院合作的研究發現，投資人第一次讀一份簡報，平均只花**三分四十四秒**。這點時間不足以讓人被說服而放下既有判斷，只夠確認或否決一個既有判斷。讀的人帶著什麼成見走進來，幾乎就會帶著同一個成見走出去，因為兩百秒裡沒有讓人慢慢改變心意的空間。所以裁決真正的任務不是替你在某張通用考卷上爭一個更高的分數，而是在計時開始之前，就把你的簡報送進那間成見本來就對你有利的房間。","l":0},{"t":"因此真正有用的問題從來不是我拿了幾分，而是**哪一間房間本來就被設計來想要我最擅長的東西**。引擎先回答這個問題，因為單單這個答案就決定了後面的一切：你去談誰、依什麼順序談、先追哪一條引薦，以及在那決定成敗的開場四分鐘裡，先用哪一項證據亮牌。分數告訴你在一場沒人同意要考的試裡表現如何；配對則告訴你該往哪裡走。這兩件事裡，只有一件能真正推進一輪募資。","l":0}]},{"h":"沒有房間等重","ps":[{"t":"三面透鏡是欲求性、可行性、存續性，世上沒有任何一位投資人會等重看待它們。寫種子前支票的天使，買的是對團隊與洞見的信念，因為此刻能買的也只有這些；成長型基金買的則是已被驗證的經濟數字，因為以它的支票尺寸，光有故事根本無從投資。同一家新創，可以在同一天於前一間房間是強烈的是，到後一間就是輕易的否，而**兩間都沒有錯**，它們用不同的錢、踩著不同的時鐘，在為不同的東西定價。把這種分歧當成雜訊，你會白追好幾個月的錯門。","l":0},{"t":"之所以沒有一把通用的尺，是因為根本沒有一位通用的買家。每一類投資人都揹著一份不是自己自由選擇的任務，那是由自家基金的形狀交下來的：**基金規模、報酬算式與時間跨度，決定了它賭得起哪一面透鏡**。靠少數大贏回收本金的小基金，必須為信念與不對稱性定價，因為一個只是還不錯的結果撐不起它的基金；對自己出資人負責的後期大基金，則必須為一個已經會複利的模型定價，因為在那個規模上它賭不起一次擲硬幣。透鏡的權重來自付錢的那張支票，不是來自品味或心情。","l":0},{"t":"這正是為什麼所謂的低分，往往只是一場戴著拒絕面具的透鏡錯配。一家靠團隊與洞見取勝的新創，被一間經濟數字優先的房間評分，會讀起來很弱，不是因為它真的弱，而是因為它**正被放在一條它此刻還不該贏的軸上被衡量**。把一家還沒營收的公司交給一間只會看回本期與世代曲線的房間，數字當然回得單薄。反過來，把裁決讀成相容性訊號，它就不再像是對你價值的審判，而開始像一張篩選你行事曆的濾網，而那正是它唯一該扮演的角色。","l":0}]},{"h":"權重隨階段移動","ps":[{"t":"早期房間幾乎只為團隊與洞見定價，其餘幾乎不看。在種子前，加速器、微型基金與天使大致把權重放在**欲求性 35、可行性 45、存續性 20**。此時還沒有真正的營收，經濟數字這面透鏡幾乎被折抵到零；沒有單位，就沒有單位經濟可以評估。撐起這張支票的，是團隊到底做不做得出他們所描述的東西，以及底層那個對市場的洞見是不是真的成立，而不只是講得漂亮。可行性領先，因為執行風險正是那個還沒被排除掉的風險。","l":1},{"t":"這不是江湖傳說，也不是某一位投資人的口味。Rebel Fund 分析了數千筆在 Y Combinator Demo Day 收集到的資料，發現**早期牽引力指標與公司估值之間，只有微弱到近乎不存在的相關性**，早期的經濟數字根本無法預測這一輪最後會怎麼定價。單單這一個發現，就是種子前房間拒絕以存續性透鏡領軍的全部理由。到了種子階段，權重轉向需求訊號，大致落在欲求性 45、可行性 25、存續性 30。問題從他們做不做得出來，移到到底有沒有人真的要，以及那股拉力是誠實地出現在數據裡，還是只出現在簡報裡。","l":0},{"t":"接著地面開始大幅傾斜，而且只往一個方向傾。到了 A 輪，多階段與產業型基金大致把權重壓成**25、25、50**，因為模型此刻必須證明它會複利放大，而不只是活著。走到成長階段，成長股權基金與家族辦公室來到**欲求性 20、可行性 20、存續性 60**，幾乎完全是經濟數字。後期的錢買的不是故事，也對故事毫無耐心；它買的是一台單位經濟已經在規模上跑得通的機器，而它為你定價的，幾乎完全落在那面種子前房間根本懶得計的透鏡上。當初替你換到第一張支票的透鏡，正是你最後一張支票會忽略的那一面。","l":2}]},{"h":"十二間房間","ps":[{"t":"分佈在這四個階段上的，大致是十二種不同的買家，每一種都為一組不同的透鏡與階段組合定價。種子前坐著**天使、加速器與微型基金**，全都倚重團隊與洞見；種子階段再加上機構型種子基金、主題驅動的產業專家，以及以營收為本的融資方，各自偏向需求或早期經濟；A 輪帶來多階段機構、深耕單一產業的專家，以及企業創投部門，開始要求模型可規模化的證據；成長階段則是成長股權、跨界基金與家族辦公室，要看的是那台機器已經在轉。十二道門，在你敲門之前，每一道門後的權重就已經固定。用同一隻手敲遍十二道門，不叫勤奮，叫浪費。","l":0},{"t":"引擎點名的，是那道任務正好在你此刻真正募資的階段、而非你希望自己在的階段，最看重你最強透鏡的門。這個配對，遠比再花一週把投影片磨亮更重要。DocSend 的數據顯示，**一份冷投、沒鎖定對象的簡報大約只被讀兩分半、極少換到會面，而一份溫暖又精準投遞的簡報會被讀超過四分鐘**，換到會面的機率也高出許多。這兩種結果之間的落差，幾乎從來不在投影片的設計，而在這份簡報有沒有落進一間本來就傾向對它最擅長之事點頭的房間。","l":1},{"t":"這正是為什麼對房間下對透鏡，勝過拿同一份簡報對所有有信箱的人亂噴。一份種子前的簡報寄給成長型基金，會敗在它本來就不該、也不可能拿得出來的經濟數字上；同一份簡報寄給為團隊與洞見定價的房間，卻可能換來一個篤定而即時的是。每一次白寄，代價還不只是換來的沉默：來自錯房間的一次拒絕，可能悄悄壞掉日後一條溫暖的引薦，而散彈式的流程也會向精明的投資人透露，你根本不了解自己的階段。**把房間配到你最強的透鏡，不是操弄流程，而是拒絕在你注定會輸的那條軸上被衡量**。","l":0}]},{"h":"從契合到路徑","ps":[{"t":"知道哪間房間契合，只是價值的一半，單靠它，也只是一張沒有路線的地圖。推進層把這份契合轉成一條你真的走得了的路：**可接觸的美國與台灣具名機構**，之所以被選出，是因為它們的投資授權正好在你此刻的階段看重你最強的那面透鏡，並附上每間機構通常如何展開一段對話、又會想先看到什麼的判讀。它是一張推進方向與值得引薦對象的地圖，不是把裁決換個說法再唸一次給你聽。這一層的意義，就在於縮短一個正確診斷與一場真正敲定的第一次會面之間的距離。","l":1},{"t":"這裡有一條界線，比這頁上任何別的東西都重要，而且它不是可以略過的小字：這些具名機構是**推進方向與可以去談的對象，絕不是任何投資的要約、招攬或保證**。引擎只負責指向，它不動用資金，也不代表任何一檔基金發言，更不替任何基金做出任何承諾。被點名為一個合理的契合對象，只是一個關於你的強項可能落在哪裡會受歡迎的建議，僅此而已。一間房間收到你的簡報後怎麼決定，完全、也只是它自己要做的決定。","l":2},{"t":"把這兩半放在一起，推導出來的紀律並不華麗，卻很簡單。把裁決讀成一次配對而非一個印記，尊重權重是真的會隨階段移動而非固定不動，然後把你嚴格有限的接觸精力，只花在那些本來就被設計來想要你最強透鏡的門上。你的簡報只有一次、短短幾分鐘的第一印象，而你很少有第二次。**整場賽局的重點，就是確保那短短幾分鐘，發生在唯一一間你的強項正好是被定價對象的房間裡**。其餘一切，都只是打扮成分數的雜訊。","l":0}]}]},{"meta":"8 分鐘閱讀 · 引擎在結論底下跑的數學","standfirst":"區間太寬不是模型失靈，是模型拒絕替太薄的資料說謊。","stat":{"n":65,"unit":"%","label":"的美國創投投資案，連投入的本金 1 倍都收不回來；只有 4% 能回收超過 10 倍","source":"Correlation Ventures，分析逾 21,000 筆投資，2004 至 2013 年"},"sections":[{"h":"數學為何必須誠實","ps":[{"t":"Correlation Ventures 統計了超過兩萬一千筆投資案，發現**其中 65% 連投入的本金都收不回來**，能回收十倍以上的僅有 4%。這句話值得讀兩遍，因為它打破了多數試算表賴以成立的直覺。這不是一條圍繞著某個平均報酬、左右對稱分散的鐘形曲線，而是一條冪律：多數結果擠在接近零的地方，全部的成果靠一條又細又猛的尾巴撐起來。在這樣的分布裡，平均值是一個幾乎不描述任何真實結果的虛構數字。任何模型只要用單一個自信的預期報酬來回答早期問題，就已經在第一行抹掉了這份資料裡唯一重要的特徵。","l":2},{"t":"這正是引擎把單點估計視為**假精準表演**的原因。像「3.2 倍報酬」這種數字之所以看起來嚴謹，恰恰是因為它把自己的不確定性藏在一個小數點後面。它讀起來像一次量測，其實只是一個穿了白袍的猜測，而那個小數點就是白袍。更深一層的問題是，假精準會傳染。你一旦接受了一個過度自信的數字，下游的每一步計算都會繼承一份證據從未包含的確定感，等模型跑到最後，你其實是在把猜測層層相乘，卻以為自己在把事實層層相乘。這樣建出來的結論可以內部無懈可擊，卻同時在描述一家並不存在的公司。","l":2},{"t":"所以整個量化層都建立在一個承諾上：**寧取誠實的區間，不要虛假的精準**。引擎寧願給你一條它守得住的寬區間，也不給你一個它站不住腳的漂亮數字，因為守得住的區間是工具，站不住腳的單點是陷阱。當區間回來得很寬，那不是數學在壓力下垮掉，而是數學忠實地報告：底下的證據就是這麼薄，輸入彼此矛盾，或這個結果確實可能落在好幾個天差地遠的位置。真正的紀律，是拒絕只為了顯得比資料更果斷，就硬把那條區間收窄，因為顯得果斷和真的正確，是兩件完全不同的工作。","l":2}]},{"h":"不靠幻想估市場","ps":[{"t":"市場那一頁是多數簡報說謊的地方，而且他們多半不是故意的。由上而下的數字從一個上兆規模的品類切下一塊聽起來合理的比例，再讓運算去把人說服，而沒有人真的逐行去守那塊比例。問題是那塊比例是被宣稱出來的，不是被賺來的。而這條捷徑的代價一點都不學術。CB Insights 檢視失敗新創的事後檢討時發現，**最常見的死因，出現在 42% 的案例裡，就是做出了一個市場根本不需要的東西**。由上而下的估法，正好是讓創辦人跳過那道唯一能攔住這件事的檢查的工具，因為龐大總量的一個百分比，看起來永遠大到足以令人安心。","l":2},{"t":"所以引擎不接受由上而下的數字自己講自己的話，而是用 **Fermi 估算**把市場從地基重建：家戶數乘以滲透率乘以每位用戶貢獻乘以使用頻率。這裡的每一項都是一個你可以拿來爭論的主張，而這正是整個演練的重點。由下而上的推算，會逼著每一個樂觀假設攤到日光下，讓人一個一個去指名、質疑、壓力測試，而不是讓它躲在單一個自信的百分比裡。當創辦人必須親口說出「三成家戶會採用、而且每週使用」，這個數字就不再聽起來像必然，而開始聽起來像它本來就該是的那種具體、可查核的賭注。","l":2},{"t":"接著引擎把兩組估算並排放在一起，盯著那道落差。當由下而上和由上而下相差**超過三倍**，那道落差不是可以折衷取中的雜訊，而是一個你還沒找到的錯誤假設。它多半藏在滲透率或使用頻率裡，這兩項最容易被包裝成必然。**這條三倍規則，會在結論成形之前先扼殺曲棍球棒式的幻想**，因為一個只在由上而下才存在的市場，往往是公司其實還沒找到真正辦法觸及的市場。真正的紀律，不是把兩個數字平均成一個妥協值，而是把這道分歧本身當成發現，然後去獵出造成它的原因。","l":2}]},{"h":"把報酬看成分布","ps":[{"t":"因為結果是厚尾的，引擎把報酬建模成一次 **Monte Carlo 模擬**，而不是單一數字。它先在最前面放一個明確的虧損機率，這是對「多數賭注會死」的誠實承認，再讓活下來的結果從一條**封頂在 300 倍的 lognormal 曲線**中抽出，好讓任何一次幻想級的抽樣，都無法悄悄把整個平均值扛在背上。跑上數千次之後，它讀出這條分布上的三個點，P10、P50 與 P90，外加乾淨翻十倍的機率。封頂不是技術細節，而是模型拒絕讓單一個想像出來的登月案膨脹整幅畫面，而這正是一條不封頂的平均值，如何對一個大半是零的投組說謊的方式。","l":2},{"t":"讓這份悲觀站得住腳的，是那些殘酷的基準機率。哈佛的 Shikhar Ghosh 研究了超過兩千家創投支持的公司，發現**約 75% 根本從來沒有把現金還給投資人**，其中三到四成更是清算收場、血本無歸。把這個數字擺到 Correlation Ventures 那條尾巴旁邊，形狀就更銳利了：一個只讀 P90、只看那個夢的模型，是在描述那 4%，同時假裝那 75% 不在場。讀完整條分布，意味著引擎把墳場看得和樂透彩券一樣清楚，並且在同一口氣裡把兩邊一起秤，而這是替一個「輸光才是基準情境」的賭注定價時，唯一誠實的做法。","l":2},{"t":"這正是為什麼**P10，也就是下檔，才是誠實的數字**。它是故事不照你的意思走時會發生的事，也是多數簡報從不揭露的那一格，因為它就是最刺痛的那一格。若引擎連這個 P10 都吞不下去，上檔的樂觀情境並不會只因為喊得大聲，就有資格喊得更大聲。一個只在 P90 才成立的結論，是把一場尾巴上的豪賭打扮成一份計畫，而跑分布的全部意義，就是要看清你手上是不是只剩這個。引擎並不禁止賭尾巴，許多偉大的結果本來就是尾巴，它只是拒絕讓其中一條被當成基準情境來引用。","l":2}]},{"h":"判決脆弱在哪","ps":[{"t":"一個只在單一組精確輸入下才成立的結論，只是姿態良好的猜測。所以引擎不替自己的結論辯護，而是主動攻擊它，問的不是這個判決對不對，而是它有多容易錯。這翻轉了一般人的直覺，也就是把模型一路建到它吐出你原本期待的答案，然後就收手。在這裡，模型是被主動推到崩解為止之後，才被信任，因為一個熬過自己壓力測試的結論，遠比一個從沒被測過的結論值錢。這件事由兩個工具完成，兩者都被設計來讓脆弱之處浮出，而不是把它抹平成某種只是看起來穩健的東西。","l":2},{"t":"**敏感度龍捲風圖**把每個透鏡各往上、往下推兩格，再依結論移動的幅度替它們排序。最長的那條就是你最脆弱的假設，是那個只要稍微錯一點、整個判決就從「要」翻成「不要」的地方。那條長棒不是該被悄悄磨平的弱點，而是一張地圖，甚至可以說是整具引擎最有用的單一產出。它清楚告訴你，該先到真實世界裡去驗證什麼，用一個客戶、一紙合約或一批用戶，而不是再多花一小時去打磨那些不管錯得多離譜、都幾乎不動結果的部分。","l":2},{"t":"情境分析接著用 **0.8、1.0 與 1.15** 三組係數，把整份結論重跑成熊、基準與牛三種版本。這三次之間的落差才是真正的產出，而不是其中任何一次單獨拿出來看。落差窄，代表這份判決講的真的是公司本身，就算把輸入猜錯一點也撐得住；落差寬，代表它多半靠你的假設同時全部成立，而這是一件脆弱得多的事。當落差很寬，**信心標記會刻意掉到低**，這不是打太極，而是誠實的報告：眼下的證據，還撐不起比這更強的主張。","l":2}]},{"h":"寬區間是一種訊號","ps":[{"t":"把這些拼在一起，會發現貫穿始終的只有一個敵人：**假精準表演**，也就是製造出資料根本不支持的確定感的習慣。一個自信的 TAM、一個單一的預期報酬、一個報到小數點兩位的判決、一個因為礙事就被無視的敏感度，全都是同一個動作，向一個證據從未賺來的數字借權威。這具引擎裡的數學，就是被特意打造來在每一個階段拒絕這個動作，從估市場、算報酬到壓力測試那份判決。用一個銳利的錯數字聽起來很聰明，比用一條誠實的寬區間容易，而這恰恰是為什麼寬區間才是更難、也更有價值的紀律。","l":2},{"t":"這種拒絕不是為謹慎而謹慎，也不是優柔寡斷。讀對了，**寬區間本身就是情報**，而且往往是整份報告裡最能付諸行動的情報。它告訴創辦人故事究竟哪裡還薄、下一步該去把哪一個假設加固，以及當前這份判決有多少是真訊號、多少是拿一個還沒發生的未來去借來的樂觀。一條建立在薄資料上的窄區間，這些什麼都告訴不了你。它只會讓人安心，同時悄悄把你的目光引向那 65%，而不是那 4%，而這是世上最昂貴的一種安慰。","l":2},{"t":"引擎的質性判讀和它的量化層，是同一種直覺用兩種語言各說了一遍。透鏡直白說出它們看見了什麼；數學說出這些數字究竟容許任何人有多確定，然後拒絕把那份確定往上進位成更好賣的東西。**是誠實的數學，讓這份判決贏得可信度**，因為一個肯坦白承認自己不知道的模型，才是它終於說自己知道的那一天，唯一值得相信的那種。其餘的一切，都只是一個姿態良好的數字，而整套紀律，就是在你簽字之前，先學會分辨兩者的差別。","l":2}]}]}],
}
